def reverse_hex_bytes(tag: str) -> str:
    """สลับลำดับ byte ของ hex idTag (ทีละ 2 ตัว) เช่น '021BAF06' <-> '06AF1B02'
    ตู้ชาร์จ (FD150A) ส่ง idTag เป็น reverse hex ของเลขที่พิมพ์บนบัตร ฟังก์ชันนี้ให้
    authorize_rfid เทียบได้ทั้ง 2 รูปแบบ → ผู้ใช้ลงทะเบียนด้วยเลขพิมพ์บนบัตรได้เลย
    (non-hex / ความยาวคี่ เช่น TEST001, AUTO- คืนค่าเดิม)"""
    s = str(tag or "").strip().upper()
    if len(s) >= 2 and len(s) % 2 == 0 and all(c in '0123456789ABCDEF' for c in s):
        return ''.join(reversed([s[i:i + 2] for i in range(0, len(s), 2)]))
    return s


# ============================================================================
# Global State
# ============================================================================
# ---------------------------------------------------------------------------
# [DB] MongoDB persistence (optional)
#
# Everything the CSMS keeps on disk as JSON files can live in a MongoDB database instead (MongoDB Atlas or a local
# server): payment ledger, customers + sign-in tokens, payment / app settings, station info + registrations,
# OCPP default-config overrides, RFID cards, charging transactions and the OCPP message log.
#
#   database.json  {"type": "mongodb", "uri": "mongodb+srv://user:pass@cluster.mongodb.net/", "db_name": "bpc_csms",
#                   "log_to_db": true, "log_retention_days": 30, "keep_json_backup": true}
#   env CSMS_MONGODB_URI overrides the uri (and switches the type to mongodb).
#
# Design: the in-memory stores stay exactly as they are (they are the working copy); when MongoDB is active, every
# store's flush() calls DB.sync_collection(), which compares each document with the copy last written and queues only
# the changed / removed ones for a background writer thread (pymongo is synchronous - the OCPP event loop must never
# wait for the network). Loads happen at start-up (and when the database is switched on from the Database tab);
# if MongoDB is unreachable at start-up the CSMS falls back to the JSON files and says so. With keep_json_backup the
# JSON files are still written, so a copy of the data always stays next to the program.
# ---------------------------------------------------------------------------
import threading as _db_threading
import queue as _db_queue
import hashlib as _db_hashlib
import time as _db_time
import sys as _db_sys

DB_SETTINGS_FILE = str((APP_DIR / 'database.json') if 'APP_DIR' in globals() else 'database.json')
DB_DEFAULTS = {'type': 'json', 'uri': '', 'db_name': 'bpc_csms', 'log_to_db': True, 'log_retention_days': 30, 'keep_json_backup': True}
DB_COLLECTIONS = ('payments', 'customers', 'tokens', 'settings', 'stations', 'rfid_cards', 'transactions', 'ocpp_logs', 'ops_users', 'ops_settings', 'ops_audit', 'ops_status', 'ops_sessions', 'ops_alerts', 'ops_notify', 'ops_tickets', 'ops_pm', 'ops_charger_access', 'ops_charger_unknown', 'ops_security', 'ops_free_active', 'ops_free_cards', 'ops_free_log', 'ops_lm_sites', 'ops_lm_log', 'ops_open_tx', 'ops_fw_files', 'ops_fw_jobs', 'ops_diag_jobs', 'ops_bookings')
DB_LOG_BATCH = 500                      # log inserts per bulk write
DB_QUEUE_MAX = 60000                    # queued operations before the oldest log inserts are dropped
DB_TXN_METER_INTERVAL = 30.0            # seconds between transaction-document updates from MeterValues
DB = None                               # the active MongoStore (None = JSON files)
DB_SETTINGS = dict(DB_DEFAULTS)
DB_STATE = {'source': 'json', 'error': '', 'started_at': '', 'fallback': False, 'pymongo': ''}


def db_load_settings() -> dict:
    data = dict(DB_DEFAULTS)
    try:
        if os.path.exists(DB_SETTINGS_FILE):
            with open(DB_SETTINGS_FILE, 'r', encoding='utf-8') as f:
                saved = json.load(f)
            if isinstance(saved, dict):
                data.update({k: saved[k] for k in DB_DEFAULTS if k in saved})
    except Exception as e:
        logger.error(f"db: failed to read {DB_SETTINGS_FILE}: {e}")
    env_uri = os.environ.get('CSMS_MONGODB_URI', '').strip()
    if env_uri:
        data['uri'] = env_uri
        data['type'] = 'mongodb'
    if os.environ.get('CSMS_MONGODB_DB', '').strip():   # [OPS] v1.9 e.g. bpc_csms_staging
        data['db_name'] = os.environ['CSMS_MONGODB_DB'].strip()
    try:
        data['log_retention_days'] = max(1, min(3650, int(data.get('log_retention_days') or 30)))
    except (TypeError, ValueError):
        data['log_retention_days'] = 30
    data['type'] = 'mongodb' if str(data.get('type')) == 'mongodb' else 'json'
    data['db_name'] = (str(data.get('db_name') or 'bpc_csms').strip() or 'bpc_csms')[:60]
    data['log_to_db'] = bool(data.get('log_to_db', True))
    data['keep_json_backup'] = bool(data.get('keep_json_backup', True))
    return data


def db_save_settings(data: dict) -> None:
    out = {k: data.get(k, DB_DEFAULTS[k]) for k in DB_DEFAULTS}
    tmp = DB_SETTINGS_FILE + '.tmp'
    with open(tmp, 'w', encoding='utf-8') as f:
        json.dump(out, f, indent=2, ensure_ascii=False)
    os.replace(tmp, DB_SETTINGS_FILE)


def db_masked_uri(uri: str) -> str:
    """mongodb+srv://user:secret@host/... -> mongodb+srv://user:••••@host/..."""
    uri = str(uri or '')
    if '@' not in uri or '://' not in uri:
        return uri
    scheme, rest = uri.split('://', 1)
    cred, host = rest.rsplit('@', 1)
    user = cred.split(':', 1)[0]
    return f'{scheme}://{user}:••••@{host}'


def _db_clean(doc):
    """A BSON-safe, detached copy of a document (datetimes / Decimals become strings like in the JSON files)."""
    return json.loads(json.dumps(doc, ensure_ascii=False, default=str))


def _db_fingerprint(doc):
    """(md5, canonical json) of a document; the json is also the BSON-safe copy that gets written."""
    try:
        s = json.dumps(doc, sort_keys=True, ensure_ascii=False, default=str)
    except TypeError:                                      # mixed int/str keys cannot be sorted
        s = json.dumps(doc, ensure_ascii=False, default=str)
    return _db_hashlib.md5(s.encode('utf-8')).hexdigest(), s


def _db_safe_keys(obj):
    """MongoDB field names must not start with '$' (and dots are paths in updates): used for write-only documents."""
    if isinstance(obj, dict):
        out = {}
        for k, v in obj.items():
            k = str(k)
            if k.startswith('$'):
                k = '＄' + k[1:]
            out[k.replace('.', '·')] = _db_safe_keys(v)
        return out
    if isinstance(obj, list):
        return [_db_safe_keys(v) for v in obj]
    return obj


class _DbWriter(_db_threading.Thread):
    """Background writer: batches queued operations into bulk writes, retries on connection errors."""

    def __init__(self, store):
        super().__init__(name='csms-db-writer', daemon=True)
        self.store = store
        self.q = _db_queue.Queue()
        self.stop_event = _db_threading.Event()
        self.written = 0
        self.errors = 0
        self.last_error = ''
        self.last_write_at = ''
        self.dropped = 0
        self.pending = 0                               # queued + in flight
        self._lock = _db_threading.Lock()
        self._startup = None                           # e.g. index setup: runs first, in this thread (keeps start-up fast)

    def add_startup_task(self, fn):
        with self._lock:
            self.pending += 1                          # flush() also waits for it
        self._startup = fn

    def put(self, coll, op):
        if self.q.qsize() > DB_QUEUE_MAX and coll == 'ocpp_logs':
            self.dropped += 1
            return
        with self._lock:
            self.pending += 1
        self.q.put((coll, op))

    def run(self):
        task, self._startup = self._startup, None
        if task is not None:
            try:
                task()
            except Exception as e:
                logger.error(f"db: start-up task failed: {e}")
            finally:
                with self._lock:
                    self.pending -= 1
        while not self.stop_event.is_set() or not self.q.empty():
            try:
                first = self.q.get(timeout=0.5)
            except _db_queue.Empty:
                continue
            batch = [first]
            deadline = _db_time.time() + 0.3
            while len(batch) < DB_LOG_BATCH and _db_time.time() < deadline:
                try:
                    batch.append(self.q.get(timeout=0.05))
                except _db_queue.Empty:
                    break
            try:
                self._write(batch)
            finally:
                with self._lock:
                    self.pending -= len(batch)

    def _write(self, batch):
        groups = {}
        for coll, op in batch:
            groups.setdefault(coll, []).append(op)
        for attempt in range(6):
            try:
                for coll, ops in groups.items():
                    self.store.db[coll].bulk_write(ops, ordered=True)
                self.written += len(batch)
                self.last_write_at = datetime.now().isoformat(timespec='seconds')
                self.last_error = ''
                return
            except Exception as e:                         # connection lost, Atlas paused, ... -> retry with backoff
                self.errors += 1
                self.last_error = '%s: %s' % (type(e).__name__, str(e)[:200])
                logger.error(f"db: write failed ({attempt + 1}/6): {self.last_error}")
                if self.stop_event.is_set():
                    return
                _db_time.sleep(min(30, 2 * (attempt + 1)))
        logger.error(f"db: giving up on a batch of {len(batch)} operations")

    def flush(self, timeout: float = 10.0):
        """Wait until every queued operation has been written (or the timeout passes)."""
        t0 = _db_time.time()
        while self.pending > 0 and _db_time.time() - t0 < timeout:
            _db_time.sleep(0.05)


_DB_DNS_CHECKED = {'at': 0.0, 'order': None}


def _db_fast_dns(max_age: float = 300.0):
    """mongodb+srv:// needs DNS SRV + TXT lookups, done by dnspython with the nameservers Windows lists for ALL adapters.
    Servers of a VPN / office network that is not connected (e.g. 10.x) come first in that list and dnspython waits
    2 s per dead server and query (measured: 6 s per lookup, ~15 s per connection). Probe every nameserver in parallel
    and put the ones that answer first, fastest first (dead ones stay at the end, in case they come back)."""
    now = _db_time.time()
    if now - _DB_DNS_CHECKED['at'] < max_age:
        return _DB_DNS_CHECKED['order']
    _DB_DNS_CHECKED['at'] = now
    try:
        import dns.resolver, dns.message, dns.query
        from concurrent.futures import ThreadPoolExecutor
        res = dns.resolver.get_default_resolver()
        servers = [str(s) for s in res.nameservers]
        if len(servers) < 2:
            return None
        query = dns.message.make_query('mongodb.net', 'NS')

        def probe(ns):
            t = _db_time.time()
            try:
                dns.query.udp(query, ns, timeout=1.0)
                return ns, _db_time.time() - t
            except Exception:
                return ns, None

        with ThreadPoolExecutor(max_workers=min(8, len(servers))) as ex:
            results = list(ex.map(probe, servers))
        alive = [ns for ns, dt in sorted((r for r in results if r[1] is not None), key=lambda r: r[1])]
        dead = [ns for ns, dt in results if dt is None]
        order = alive + dead
        if alive and order != servers:
            res.nameservers = order
            logger.info(f"db: DNS servers reordered for the MongoDB lookups: {alive} answer, {dead} do not")
        _DB_DNS_CHECKED['order'] = order
        return order
    except Exception as e:
        logger.info(f"db: DNS probe skipped ({e})")
        return None


class MongoStore:
    def __init__(self, uri: str, db_name: str = 'bpc_csms', log_retention_days: int = 30, timeout_ms: int = 8000, light: bool = False):
        """light=True: connection test only (no index setup, no writer thread)."""
        import pymongo                                     # pip install "pymongo[srv]"
        from pymongo import ReplaceOne, UpdateOne, DeleteOne, InsertOne
        self._ops = (ReplaceOne, UpdateOne, DeleteOne, InsertOne)
        kwargs = {'serverSelectionTimeoutMS': timeout_ms, 'connectTimeoutMS': timeout_ms, 'appname': 'BPC-CSMS',
                  'retryWrites': True}
        try:
            import certifi
            if uri.startswith('mongodb+srv://') or 'tls=true' in uri.lower() or 'ssl=true' in uri.lower():
                kwargs['tlsCAFile'] = certifi.where()
        except Exception:
            pass
        self.uri, self.db_name = uri, db_name
        t0 = _db_time.time()
        if uri.startswith('mongodb+srv://'):
            _db_fast_dns()
        self.client = pymongo.MongoClient(uri, **kwargs)
        try:
            info = self.client.server_info()               # one round trip: proves the connection (and the login) + version
        except Exception:
            try:
                self.client.close()
            except Exception:
                pass
            raise
        self.server_version = str((info or {}).get('version', ''))
        self.connect_ms = int(1000 * (_db_time.time() - t0))
        self.db = self.client[db_name]
        self.pymongo_version = getattr(pymongo, 'version', '')
        self.retention_days = int(log_retention_days)
        self._snap = {}                                    # collection -> {id: fingerprint}
        self._txn_meter_at = {}
        self.writer = _DbWriter(self)
        self.connected_at = datetime.now().isoformat(timespec='seconds')
        if light:
            return
        self.writer.add_startup_task(self._ensure_indexes)  # ~10 round trips: in the background, not on the start-up path
        self.writer.start()
        logger.info(f"db: connected to MongoDB {self.server_version} database '{db_name}' in {self.connect_ms} ms")

    # ---- schema
    def _ensure_indexes(self):
        try:
            logs = self.db['ocpp_logs']
            want = int(self.retention_days) * 86400
            existing = logs.index_information()
            ttl = existing.get('ts_ttl')
            if ttl is not None and int(ttl.get('expireAfterSeconds', -1)) != want:
                logs.drop_index('ts_ttl')
                ttl = None
            if ttl is None:
                logs.create_index('ts', name='ts_ttl', expireAfterSeconds=want)
            logs.create_index([('date', 1), ('cp_id', 1), ('ts', 1)], name='date_cp_ts')
            self.db['payments'].create_index([('created_at', -1)], name='created')
            self.db['payments'].create_index([('customer_id', 1)], name='customer')
            self.db['payments'].create_index([('cp_id', 1), ('transaction_id', 1)], name='cp_txn')
            self.db['customers'].create_index([('phone', 1)], name='phone')
            self.db['customers'].create_index([('email', 1)], name='email')
            self.db['tokens'].create_index([('expires', 1)], name='expires')
            self.db['transactions'].create_index([('cp_id', 1), ('start_time', -1)], name='cp_start')
            self.db['transactions'].create_index([('id_tag', 1)], name='id_tag')
        except Exception as e:
            logger.error(f"db: index setup failed: {e}")

    # ---- writes (queued)
    def sync_collection(self, coll: str, docs: dict, delete_missing: bool = True):
        """Upsert the documents that changed since the last sync, delete the ones that disappeared."""
        ReplaceOne, UpdateOne, DeleteOne, InsertOne = self._ops
        snap = self._snap.setdefault(coll, {})
        changed = deleted = 0
        seen = set()
        for key, doc in list(docs.items()):
            key = str(key)
            seen.add(key)
            fp, s = _db_fingerprint(doc)
            if snap.get(key) == fp:
                continue
            clean = json.loads(s)
            if isinstance(clean, dict):
                clean['_id'] = key
            else:
                clean = {'_id': key, 'value': clean}
            self.writer.put(coll, ReplaceOne({'_id': key}, clean, upsert=True))
            snap[key] = fp
            changed += 1
        if delete_missing:
            for key in [k for k in snap if k not in seen]:
                self.writer.put(coll, DeleteOne({'_id': key}))
                del snap[key]
                deleted += 1
        return changed, deleted

    def put_doc(self, coll: str, key: str, doc: dict):
        ReplaceOne = self._ops[0]
        clean = _db_clean(doc)
        clean['_id'] = str(key)
        self.writer.put(coll, ReplaceOne({'_id': str(key)}, clean, upsert=True))

    def set_fields(self, coll: str, key: str, fields: dict):
        UpdateOne = self._ops[1]
        self.writer.put(coll, UpdateOne({'_id': str(key)}, {'$set': _db_safe_keys(_db_clean(fields))}, upsert=True))

    def delete_doc(self, coll: str, key: str):
        DeleteOne = self._ops[2]
        self.writer.put(coll, DeleteOne({'_id': str(key)}))
        self._snap.get(coll, {}).pop(str(key), None)

    def forget_snapshot(self, coll: str = None):
        if coll:
            self._snap.pop(coll, None)
        else:
            self._snap.clear()

    # ---- reads (synchronous: call at start-up or from a worker thread)
    def load_all(self, coll: str) -> dict:
        """{id: document} - and remember the fingerprints so the first sync() does not rewrite everything."""
        out, snap = {}, {}
        for d in self.db[coll].find({}):
            key = str(d.pop('_id'))
            if set(d.keys()) == {'value'}:
                d = d['value']
            out[key] = d
            snap[key] = _db_fingerprint(d)[0]
        self._snap[coll] = snap
        return out

    def load_doc(self, coll: str, key: str):
        d = self.db[coll].find_one({'_id': str(key)})
        if d is None:
            return None
        d.pop('_id', None)
        return d

    def count(self, coll: str) -> int:
        try:
            return int(self.db[coll].estimated_document_count())
        except Exception:
            return -1

    # ---- OCPP message log
    def log(self, entry: dict):
        InsertOne = self._ops[3]
        doc = _db_safe_keys(_db_clean(entry))
        try:
            doc['ts'] = datetime.fromisoformat(str(entry.get('full_timestamp') or '').replace('Z', '+00:00'))
            doc['ts'] = doc['ts'].astimezone(timezone.utc)   # [OPS] v1.11 stored in UTC
        except (TypeError, ValueError):
            doc['ts'] = datetime.now(timezone.utc)
        self.writer.put('ocpp_logs', InsertOne(doc))

    def logs_for_date(self, date_str: str, cp_id: str = None, limit: int = 50000) -> list:
        q = {'date': date_str}
        if cp_id:
            q['cp_id'] = cp_id
        out = []
        for d in self.db['ocpp_logs'].find(q, {'_id': 0, 'ts': 0}).sort('ts', 1).limit(limit):
            out.append(d)
        return out

    def log_dates(self) -> list:
        try:
            return sorted((str(d) for d in self.db['ocpp_logs'].distinct('date')), reverse=True)
        except Exception as e:
            logger.error(f"db: log dates failed: {e}")
            return []

    # ---- charging transactions (one document per OCPP transaction)
    def txn_start(self, cp_id: str, connector_id: int, id_tag: str, txn_id, meter_start, timestamp: str):
        self.set_fields('transactions', f'{cp_id}:{txn_id}', {
            'cp_id': cp_id, 'transaction_id': txn_id, 'connector_id': connector_id, 'id_tag': id_tag, 'meter_start': meter_start,
            'start_time': timestamp, 'state': 'charging', 'updated_at': datetime.now().isoformat(timespec='seconds')})

    def txn_meter(self, cp_id: str, txn_id, energy_wh=None, power_w=None, soc=None):
        if txn_id is None:
            return
        key = f'{cp_id}:{txn_id}'
        now = _db_time.time()
        if now - self._txn_meter_at.get(key, 0) < DB_TXN_METER_INTERVAL:
            return
        self._txn_meter_at[key] = now
        fields = {'updated_at': datetime.now().isoformat(timespec='seconds')}
        if energy_wh is not None:
            fields['last_energy_wh'] = energy_wh
        if power_w is not None:
            fields['last_power_w'] = power_w
        if soc is not None:
            fields['last_soc'] = soc
        self.set_fields('transactions', key, fields)

    def txn_stop(self, cp_id: str, txn_id, meter_stop, reason: str, energy_wh, timestamp: str):
        self._txn_meter_at.pop(f'{cp_id}:{txn_id}', None)
        self.set_fields('transactions', f'{cp_id}:{txn_id}', {
            'cp_id': cp_id, 'transaction_id': txn_id, 'meter_stop': meter_stop, 'stop_time': timestamp, 'stop_reason': reason,
            'energy_wh': energy_wh, 'state': 'completed', 'updated_at': datetime.now().isoformat(timespec='seconds')})

    # ---- status
    def stats(self) -> dict:
        w = self.writer
        return {'connected': True, 'server_version': self.server_version, 'pymongo': self.pymongo_version, 'db_name': self.db_name,
                'connected_at': self.connected_at, 'queued': w.pending, 'written': w.written, 'errors': w.errors,
                'last_error': w.last_error, 'last_write_at': w.last_write_at, 'dropped_logs': w.dropped,
                'collections': {c: self.count(c) for c in DB_COLLECTIONS}}

    def flush(self, timeout: float = 10.0):
        self.writer.flush(timeout)

    def close(self):
        try:
            self.writer.stop_event.set()
            if self.writer.is_alive():
                self.writer.join(timeout=15)
        except Exception:
            pass
        try:
            self.client.close()
        except Exception:
            pass


# ---- start-up ----------------------------------------------------------------------------------------------------
def _db_process_role() -> str:
    """launcher | v201 | csms (only the OCPP 1.6 CSMS process talks to the database)."""
    argv = _db_sys.argv
    if len(argv) >= 3 and argv[1] == '--csms-child':
        return 'v201' if argv[2] == '2.0.1' else 'csms'
    if __name__ == '__main__':
        return 'launcher'
    return 'csms'


def db_connect(settings: dict, quiet: bool = False):
    """Open the configured database (returns the store) or raise."""
    return MongoStore(settings['uri'], settings.get('db_name') or 'bpc_csms', settings.get('log_retention_days') or 30)


def db_startup():
    """Called once at import time: read database.json and connect when MongoDB is configured."""
    global DB, DB_SETTINGS
    DB_SETTINGS = db_load_settings()
    DB_STATE['started_at'] = datetime.now().isoformat(timespec='seconds')
    role = _db_process_role()
    try:
        import pymongo
        DB_STATE['pymongo'] = getattr(pymongo, 'version', 'yes')
    except Exception:
        DB_STATE['pymongo'] = ''
    if DB_SETTINGS.get('type') != 'mongodb' or not DB_SETTINGS.get('uri'):
        DB_STATE['source'] = 'json'
        return
    if role != 'csms':
        DB_STATE['source'] = 'json'                        # the launcher / 2.0.1 process keeps its hands off the database
        return
    if not DB_STATE['pymongo']:
        DB_STATE.update(source='json', fallback=True, error='pymongo is not installed (pip install "pymongo[srv]") - using the JSON files')
        logger.error('db: ' + DB_STATE['error'])
        return
    try:
        DB = db_connect(DB_SETTINGS)
        DB_STATE.update(source='mongodb', error='', fallback=False)
    except Exception as e:
        DB = None
        DB_STATE.update(source='json', fallback=True, error='MongoDB unreachable at start-up (%s) - using the JSON files' % str(e)[:200])
        logger.error('db: ' + DB_STATE['error'])


def db_keep_files() -> bool:
    """Should the stores still write their JSON files?  (always when the database is off)"""
    return DB is None or bool(DB_SETTINGS.get('keep_json_backup', True))


def db_load_collection(coll: str, file_loader):
    """Documents for a store: from MongoDB when active, else from the JSON file.
    An empty collection next to an existing file means 'first start with the database' -> import the file (migration)."""
    if DB is None:
        return file_loader() or {}, 'json'
    try:
        docs = DB.load_all(coll)
    except Exception as e:
        logger.error(f"db: loading {coll} failed ({e}) - using the JSON file")
        return file_loader() or {}, 'json'
    if docs:
        return docs, 'mongodb'
    from_file = file_loader() or {}
    if from_file:
        DB.sync_collection(coll, from_file)
        logger.info(f"db: imported {len(from_file)} {coll} from the JSON file into MongoDB")
    return from_file, 'mongodb'


def db_load_doc(coll: str, key: str, file_loader):
    """One settings-like document (same migration rule as db_load_collection)."""
    if DB is None:
        return file_loader(), 'json'
    try:
        doc = DB.load_doc(coll, key)
    except Exception as e:
        logger.error(f"db: loading {coll}/{key} failed ({e}) - using the JSON file")
        return file_loader(), 'json'
    if doc is not None:
        return doc, 'mongodb'
    from_file = file_loader()
    if from_file:
        DB.put_doc(coll, key, from_file)
        logger.info(f"db: imported {coll}/{key} from the JSON file into MongoDB")
    return from_file, 'mongodb'


