    @on(Action.start_transaction)
    async def on_start_transaction(self, connector_id: int, id_tag: str, meter_start: int, timestamp: str, **kwargs):
        # Authorize the idTag
        # ถ้า transaction นี้เกิดจาก RemoteStart ที่ operator สั่งจาก CSMS -> Accepted (authorized โดย operator)
        # ไม่งั้นตรวจตามรายการบัตรปกติ (บัตรไม่ลงทะเบียน = Invalid ตามเดิม)
        _rs_key = str(id_tag).upper()
        _bk_gate = ops_bk_start_gate(self.id, connector_id, id_tag, kwargs.get('reservation_id'), timestamp)   # [OPS] v1.12 bookings
        if _bk_gate is not None:
            id_tag_info = _bk_gate
        elif app_state.take_remote_start_pending(self.id, connector_id, id_tag):
            id_tag_info = {'status': AuthorizationStatus.accepted}
            logger.info(f"StartTransaction C{connector_id} idTag={_rs_key}: "
                        f"Accepted (CSMS-initiated RemoteStart)")
        else:
            id_tag_info = (ops_free_authorize(self.id, connector_id, id_tag, start=True)   # [OPS] v1.7 free charging
                           or app_state.authorize_rfid(id_tag))
        
        txn_id = app_state.next_transaction_id()

        # A connector can only have one active transaction at a time. Drop any stale
        # entry still parked on this connector so Remote Stop never targets an old id.
        for stale_id in [tid for tid, t in self.data.transactions.items()
                         if t.get('connector_id') == connector_id]:
            del self.data.transactions[stale_id]
            self._mv_interval_buffer.pop(str(stale_id), None)

        self.data.transactions[txn_id] = {
            'connector_id': connector_id,
            'id_tag': id_tag,
            'meter_start': meter_start,
            'start_time': timestamp
        }

        # Start a fresh MeterValues interval buffer for this transaction (Test 5)
        self._mv_interval_buffer[str(txn_id)] = {}

        # [PAYMENT] link the transaction to its prepaid session (idTag PAY-...)
        if str(id_tag_info.get('status', '')).split('.')[-1].lower() == 'accepted':
            await pay_on_start_transaction(self.id, connector_id, id_tag, txn_id, meter_start, timestamp)
        db_on_transaction_start(self.id, connector_id, id_tag, txn_id, meter_start, timestamp)   # [DB]
        ops_emit('tx_start', cp_id=self.id, connector=connector_id, txn_id=txn_id, id_tag=id_tag,   # [OPS]
                 meter_start=meter_start, timestamp=timestamp, reservation_id=kwargs.get('reservation_id'),
                 accepted=str(id_tag_info.get('status', '')).split('.')[-1].lower() == 'accepted')

        app_state.add_log('⬅️ IN', self.id, 'StartTransaction', {
            'connector': connector_id,
            'idTag': id_tag,
            'txnId': txn_id,
            'meterStart': meter_start,
            'meterContext': 'Transaction.Begin',  # Implicit context
            'authStatus': str(id_tag_info.get('status', 'Accepted'))
        })
        
        await self._notify_update()
        
        return call_result.StartTransaction(
            transaction_id=txn_id,
            id_tag_info=id_tag_info
        )

    def _check_stoptxn_aligned_interval(self, transaction_id, txn_meter_values: list) -> Optional[list]:
        """Verify the charger sent MeterValues at the configured interval during the
        transaction: ClockAlignedDataInterval for Sample.Clock,
        MeterValueSampleInterval for Sample.Periodic.

        Timestamps come from two sources merged per context:
          1. MeterValues.req sent during the transaction (buffered live) — this is
             where most chargers put periodic/aligned samples.
          2. StopTransaction.req transactionData (some chargers bundle them here).
        """
        interval_by_context = {
            'Sample.Clock': 'ClockAlignedDataInterval',
            'Sample.Periodic': 'MeterValueSampleInterval',
        }

        # Collect timestamps per context from both sources
        timestamps_by_context: Dict[str, set] = {ctx: set() for ctx in interval_by_context}

        # Source 1: live buffer of MeterValues during this transaction
        buffered = self._mv_interval_buffer.get(str(transaction_id), {})
        for ctx, ts_list in buffered.items():
            if ctx in timestamps_by_context:
                timestamps_by_context[ctx].update(t for t in ts_list if t)

        # Source 2: transactionData carried in StopTransaction.req
        for mv in txn_meter_values or []:
            ctx = mv.get('context')
            ts = mv.get('timestamp')
            if ctx in timestamps_by_context and ts:
                timestamps_by_context[ctx].add(ts)

        results = []
        for context, config_key in interval_by_context.items():
            try:
                expected_interval = int(app_state.default_config.get(config_key, {}).get('value', 0) or 0)
            except (TypeError, ValueError):
                expected_interval = 0

            timestamps = sorted(timestamps_by_context[context])
            sample_count = len(timestamps)

            # Not enough data to measure an interval for this context
            if sample_count < 2:
                if expected_interval > 0:
                    # Interval is configured but we saw <2 samples — report as inconclusive
                    results.append({
                        'context': context,
                        'configKey': config_key,
                        'expectedIntervalSec': expected_interval,
                        'sampleCount': sample_count,
                        'observedGapsSec': [],
                        'matched': None,
                        'note': 'ข้อมูลไม่พอ (ต้องมี timestamp อย่างน้อย 2 จุด)'
                    })
                continue

            parsed = []
            for ts in timestamps:
                try:
                    parsed.append(datetime.fromisoformat(ts.replace('Z', '+00:00')))
                except ValueError:
                    pass
            parsed.sort()
            if len(parsed) < 2:
                continue

            gaps = [
                round((parsed[i + 1] - parsed[i]).total_seconds())
                for i in range(len(parsed) - 1)
            ]

            tolerance = 2  # seconds, allow send/clock jitter
            mismatched_gaps = [g for g in gaps if abs(g - expected_interval) > tolerance]

            entry = {
                'context': context,
                'configKey': config_key,
                'expectedIntervalSec': expected_interval,
                'sampleCount': sample_count,
                'observedGapsSec': gaps,
                'mismatchedGapsSec': mismatched_gaps,
            }
            if expected_interval > 0:
                entry['matched'] = len(mismatched_gaps) == 0
            else:
                # Charger sent samples for a context whose interval is disabled (0)
                entry['matched'] = None
                entry['note'] = f'{config_key}=0 (ปิดอยู่) แต่ charger ยังส่ง {context}'
            results.append(entry)

        return results or None

    @on(Action.stop_transaction)
    async def on_stop_transaction(self, meter_stop: int, timestamp: str, transaction_id: int, **kwargs):
        reason = kwargs.get('reason', 'Local')
        transaction_data = kwargs.get('transaction_data', [])
        ops_ct_rehydrate(self, transaction_id)   # [OPS] v1.10 session that began before a reconnect / restart
        _ops_txn = dict(self.data.transactions.get(transaction_id) or {})   # [OPS] facts of the session before it is removed

        energy = 0
        if transaction_id in self.data.transactions:
            txn = self.data.transactions[transaction_id]
            energy = meter_stop - txn['meter_start']
            snap = self.data.meter.setdefault(txn.get('connector_id', 0), {})
            snap['power_w'] = 0.0                                   # session over -> no power on this connector
            snap['energy_wh'] = float(meter_stop)
            del self.data.transactions[transaction_id]

        # [PAYMENT] settle the prepaid session of this transaction (used / remaining / refund due)
        await pay_on_stop_transaction(self.id, transaction_id, meter_stop, reason, energy)
        db_on_transaction_stop(self.id, transaction_id, meter_stop, reason, energy, timestamp)   # [DB]
        ops_emit('tx_stop', cp_id=self.id, txn_id=transaction_id, meter_stop=meter_stop, reason=reason,   # [OPS]
                 energy_wh=energy, timestamp=timestamp, txn=_ops_txn, id_tag=kwargs.get('id_tag') or _ops_txn.get('id_tag', ''))

        # Parse transaction_data for meter values with context + timestamp
        txn_meter_values = []
        if transaction_data:
            for mv in transaction_data:
                mv_timestamp = mv.get('timestamp', '')
                for sv in mv.get('sampledValue', mv.get('sampled_value', [])):
                    txn_meter_values.append({
                        'timestamp': mv_timestamp,
                        'measurand': sv.get('measurand', 'Energy.Active.Import.Register'),
                        'value': sv.get('value', '0'),
                        'unit': sv.get('unit', ''),
                        'context': sv.get('context', 'Transaction.End'),
                        'location': sv.get('location', 'Outlet')
                    })

        # Test 5: verify the charger sent MeterValues (Sample.Periodic / Sample.Clock)
        # at the configured interval during this transaction. Uses timestamps buffered
        # from live MeterValues.req plus any carried in transactionData.
        aligned_test = self._check_stoptxn_aligned_interval(transaction_id, txn_meter_values)

        # Done with this transaction's interval buffer
        self._mv_interval_buffer.pop(str(transaction_id), None)

        log_data = {
            'txnId': transaction_id,
            'meterStop': meter_stop,
            'meterContext': 'Transaction.End',  # Implicit context
            'energy': f"{energy} Wh",
            'reason': reason
        }

        if txn_meter_values:
            log_data['transactionData'] = txn_meter_values
        if aligned_test:
            log_data['stopTxnAlignedTest'] = aligned_test

        app_state.add_log('⬅️ IN', self.id, 'StopTransaction', log_data)
        
        await self._notify_update()
        
        return call_result.StopTransaction(
            id_tag_info={'status': AuthorizationStatus.accepted}
        )

    @on(Action.meter_values)
    async def on_meter_values(self, connector_id: int, meter_value: list, **kwargs):
        # Extract key values with context and location
        values = []
        transaction_id = kwargs.get('transaction_id')
        meter_changed = False
        
        for mv in meter_value:
            timestamp = mv.get('timestamp', '')
            mv_contexts = set()
            for sv in mv.get('sampledValue', mv.get('sampled_value', [])):
                measurand = sv.get('measurand', 'Energy.Active.Import.Register')
                value = sv.get('value', '0')
                unit = sv.get('unit', '')
                context = sv.get('context', 'Sample.Periodic')  # Default per OCPP 1.6
                location = sv.get('location', 'Outlet')  # Default per OCPP 1.6
                phase = sv.get('phase', '')
                mv_contexts.add(context)

                values.append({
                    'measurand': measurand,
                    'value': value,
                    'unit': unit,
                    'context': context,
                    'location': location,
                    'phase': phase
                })

            # Buffer this MeterValues timestamp per context for the active
            # transaction, so Test 5 can verify send intervals at StopTransaction.
            # (Charger sends Sample.Periodic/Sample.Clock as separate MeterValues.req
            #  during the transaction, not bundled into StopTransaction.transactionData.)
            if transaction_id is not None and timestamp:
                buf = self._mv_interval_buffer.setdefault(str(transaction_id), {})
                for ctx in mv_contexts:
                    if ctx in ('Sample.Periodic', 'Sample.Clock'):
                        buf.setdefault(ctx, []).append(timestamp)
        
        # Create summary for log
        summary = {}
        contexts_found = set()
        locations_found = set()
        
        for v in values:
            key = v['measurand']
            if v['phase']:
                key += f".{v['phase']}"
            summary[key] = f"{v['value']} {v['unit']}"
            contexts_found.add(v['context'])
            locations_found.add(v['location'])
        
        app_state.add_log('⬅️ IN', self.id, 'MeterValues', {
            'connector': connector_id,
            'txnId': transaction_id,
            'contexts': list(contexts_found),
            'locations': list(locations_found),
            'values': summary,
            'details': values  # Full details for inspection
        })

        # Snapshot for the fleet overview (power / energy / SoC per connector)
        snap = dict(self.data.meter.get(connector_id, {}))
        for v in values:
            if v['phase']:
                continue                                    # per-phase values: keep the totals only
            try:
                val = float(v['value'])
            except (TypeError, ValueError):
                continue
            unit = str(v['unit'] or '').lower()
            m = v['measurand']
            if m == 'Power.Active.Import':
                snap['power_w'] = val * 1000.0 if unit == 'kw' else val
            elif m == 'Energy.Active.Import.Register':
                snap['energy_wh'] = val * 1000.0 if unit == 'kwh' else val
            elif m == 'SoC':
                snap['soc'] = val
            elif m == 'Current.Import':
                snap['current_a'] = val
            elif m == 'Voltage':
                snap['voltage_v'] = val
        snap['timestamp'] = (meter_value[-1].get('timestamp', '') if meter_value else '') or datetime.now().isoformat(timespec='seconds')
        self.data.meter[connector_id] = snap
        meter_changed = True

        # [PAYMENT] prepaid budget: energy used -> amount used; RemoteStop when the budget is used up
        _pay_txn = transaction_id if transaction_id is not None else next((tid for tid, t in self.data.transactions.items() if t.get('connector_id') == connector_id), None)
        await pay_on_meter_values(self.id, connector_id, _pay_txn, snap.get('energy_wh'), snap.get('power_w'))
        db_on_transaction_meter(self.id, _pay_txn, snap.get('energy_wh'), snap.get('power_w'), snap.get('soc'))   # [DB]
        ops_emit('meter', cp_id=self.id, connector=connector_id, txn_id=_pay_txn, energy_wh=snap.get('energy_wh'),   # [OPS]
                 power_w=snap.get('power_w'), soc=snap.get('soc'))

        # Reconcile transaction tracking with the CP's ground truth. On reconnect a
        # fresh CentralSystem is created with an empty transactions dict while the CP
        # is still mid-transaction and keeps sending its real active transactionId in
        # MeterValues. Without this, Remote Stop can't find the id (or the frontend's
        # stale id no longer matches the CP) → "หยุดไม่ได้". Trust the CP's id.
        if transaction_id is not None and transaction_id not in self.data.transactions:
            # Drop any stale/divergent entry still parked on this connector
            for stale_id in [tid for tid, t in self.data.transactions.items()
                             if t.get('connector_id') == connector_id]:
                del self.data.transactions[stale_id]
            # Rebuild a minimal active-transaction record from what the CP reported
            meter_now = 0
            for v in values:
                if v['measurand'] == 'Energy.Active.Import.Register':
                    try:
                        meter_now = int(float(v['value']))
                    except (TypeError, ValueError):
                        meter_now = 0
                    break
            self.data.transactions[transaction_id] = {
                'connector_id': connector_id,
                'id_tag': '',
                'meter_start': meter_now,
                'start_time': timestamp or '',
                'reconstructed': True,  # not started via this CSMS session
            }
            ops_ct_rehydrate(self, transaction_id, connector_id)   # [OPS] v1.10 the facts kept when the session started
            meter_changed = True
        if meter_changed:
            await self._notify_update()

        return call_result.MeterValues()

    @on(Action.data_transfer)
    async def on_data_transfer(self, vendor_id: str, **kwargs):
        message_id = kwargs.get('message_id', '')
        data = kwargs.get('data', '')
        app_state.add_log('⬅️ IN', self.id, 'DataTransfer', {
            'vendor': vendor_id,
            'message': message_id,
            'data': data
        })
        # [PAYMENT] ตู้แจ้งผลชำระเงิน (PaymentReceived มาก่อน Authorize) / ผลสรุป (PaymentSettled)
        # เก็บไว้ให้ authorize_rfid() และ log อ่านง่าย — ตอบ Accepted เสมอ ตู้ไม่ block ถ้าตอบอื่น
        if vendor_id == PAYMENT_VENDOR_ID and message_id in PAYMENT_MESSAGE_IDS:
            entry = app_state.record_payment_event(self.id, message_id, data)
            await pay_on_charger_event(self.id, message_id, entry)   # [PAYMENT] charger-terminal payments share the ledger
            if entry is not None:
                # log ซ้ำอีกบรรทัดแบบอ่านง่าย (action = PaymentReceived/PaymentSettled) ให้กรองใน UI ได้
                app_state.add_log('⬅️ IN', self.id, message_id, {
                    'connector': entry.get('connectorId'),
                    'idTag': entry.get('idTag'),
                    'state': entry.get('state'),
                    'gateway': entry.get('gateway'),
                    'invoiceNo': entry.get('invoiceNo'),
                    'paidAmount': entry.get('paidAmount') or entry.get('amount'),
                    'currency': entry.get('currency', 'THB'),
                    'paidRef': entry.get('paidRef'),
                    'txnId': entry.get('transactionId'),
                    'usedKwh': entry.get('usedKwh'),
                    'usedAmount': entry.get('usedAmount'),
                    'remainingAmount': entry.get('remainingAmount'),
                    'refundStatus': entry.get('refundStatus'),
                    'endReason': entry.get('endReason'),
                })
        return call_result.DataTransfer(status='Accepted')

