    # ========================================================================
    # Commands to send to CP
    # ========================================================================
    async def cmd_remote_start(self, id_tag: str, connector_id: int = None):
        _bk = await ops_bk_before_remote_start(self, id_tag, connector_id)   # [OPS] v1.12 a connector kept for a booking
        if _bk is not None:
            return _bk
        kwargs = {'id_tag': id_tag}
        if connector_id:
            kwargs['connector_id'] = connector_id
        app_state.add_log('➡️ OUT', self.id, 'RemoteStartTransaction', kwargs)
        response = await self.call(call.RemoteStartTransaction(**kwargs))
        status_str = str(response.status)
        # CP รับ RemoteStart -> จำ idTag ไว้ให้ StartTransaction ที่ตามมาได้ Accepted (อายุ 120s กันค้าง)
        # split('.')[-1] รองรับทั้ง "Accepted" และ "RemoteStartStopStatus.accepted"
        # จำแยกตาม connector: สั่งหลายหัวด้วยบัตรใบเดียวกัน ทุกหัวต้องได้ตั๋วของตัวเอง
        if status_str.split('.')[-1].lower() == 'accepted':
            _rs_cid = int(connector_id) if connector_id else None
            app_state.prune_remote_start_pending()
            app_state.remote_start_pending[(self.id, _rs_cid, str(id_tag).upper())] = \
                datetime.now() + timedelta(seconds=120)
        return {'status': status_str}

    async def cmd_remote_stop(self, transaction_id: int):
        app_state.add_log('➡️ OUT', self.id, 'RemoteStopTransaction', {'txnId': transaction_id})
        response = await self.call(call.RemoteStopTransaction(transaction_id=transaction_id))
        return {'status': str(response.status)}

