async def handle_api_logs_clear(request):
    """Clear logs for a specific date"""
    try:
        data = await request.json()
        date_str = data.get('date')
        
        if not date_str:
            return web.json_response({'error': 'date is required'}, status=400)
        
        deleted = []
        for log_file in (f'ocpp_logs_{date_str}.json', f'ocpp_logs_{date_str}.jsonl'):
            if os.path.exists(log_file):
                os.remove(log_file)
                deleted.append(log_file)
        if deleted:
            return web.json_response({'success': True, 'deleted': ', '.join(deleted)})
        else:
            return web.json_response({'error': 'Log file not found'}, status=404)
            
    except Exception as e:
        return web.json_response({'error': str(e)}, status=500)

