DIAGNOSTICS_DIR = "diagnostics_received"  # โฟลเดอร์เก็บไฟล์ที่ CP upload มา
os.makedirs(DIAGNOSTICS_DIR, exist_ok=True)


async def handle_diagnostics_upload(request):
    """รับไฟล์ diagnostics ที่ CP upload มาผ่าน HTTP PUT
    
    CP จะเรียก:  PUT http://<csms-ip>:<web-port>/api/diagnostics/upload/<filename>
    Body = raw binary ของไฟล์ zip
    """
    filename = request.match_info['filename']
    
    # ป้องกัน path traversal
    safe_name = os.path.basename(filename)
    if not safe_name:
        return web.json_response({'error': 'Invalid filename'}, status=400)
    
    try:
        # อ่าน body ทั้งหมด
        data = await request.read()
        
        if not data:
            return web.json_response({'error': 'Empty body'}, status=400)
        
        # บันทึกไฟล์
        file_path = os.path.join(DIAGNOSTICS_DIR, safe_name)
        with open(file_path, 'wb') as f:
            f.write(data)
        
        file_size = len(data)
        logger.info(f"📥 Diagnostics received: {safe_name} ({file_size:,} bytes)")
        
        # บันทึก log ใน app_state
        app_state.add_log('📥 IN', 'SYSTEM', 'DiagnosticsFileReceived', {
            'fileName': safe_name,
            'size': file_size
        })
        
        # Broadcast ไปยัง WebSocket clients (Web UI จะเห็นทันที)
        await app_state.broadcast('diagnostics_received', {
                'fileName': safe_name,
                'size': file_size,
                'timestamp': datetime.now().isoformat()
            })

        return web.Response(status=200, text='OK')
        
    except Exception as e:
        logger.error(f"Diagnostics upload error: {e}")
        return web.json_response({'error': str(e)}, status=500)


async def handle_diagnostics_list(request):
    """แสดงรายการไฟล์ diagnostics ที่ได้รับจาก CP"""
    try:
        files = []
        if os.path.isdir(DIAGNOSTICS_DIR):
            for fname in sorted(os.listdir(DIAGNOSTICS_DIR), reverse=True):
                fpath = os.path.join(DIAGNOSTICS_DIR, fname)
                if os.path.isfile(fpath):
                    stat = os.stat(fpath)
                    files.append({
                        'name': fname,
                        'size': stat.st_size,
                        'modified': datetime.fromtimestamp(stat.st_mtime).isoformat()
                    })
        return web.json_response({'files': files})
    except Exception as e:
        return web.json_response({'error': str(e)}, status=500)


async def handle_diagnostics_download(request):
    """Download ไฟล์ diagnostics จาก Web UI"""
    filename = request.match_info['filename']
    safe_name = os.path.basename(filename)
    file_path = os.path.join(DIAGNOSTICS_DIR, safe_name)
    
    if not os.path.isfile(file_path):
        return web.json_response({'error': 'File not found'}, status=404)
    
    try:
        with open(file_path, 'rb') as f:
            data = f.read()
        
        content_type = 'application/zip' if safe_name.endswith('.zip') else 'application/octet-stream'
        return web.Response(
            body=data,
            headers={
                'Content-Type': content_type,
                'Content-Disposition': f'attachment; filename="{safe_name}"'
            }
        )
    except Exception as e:
        return web.json_response({'error': str(e)}, status=500)

# ============================================================================
# FTP Log Download (ดึง log จากหัวชาร์จโดยตรง)
# ============================================================================
async def handle_ftp_download(request):
    """Download ethlog files from charger via FTP"""
    import asyncio
    from ftplib import FTP
    import zipfile
    import re

    charger_id = request.match_info['charger_id']
    latest = int(request.query.get('latest', 0))  # 0 = all

    ftp_config = {
        'charger1': {'host': '192.168.0.8', 'path': '/log/'},
        'charger2': {'host': '192.168.0.9', 'path': '/log/'}
    }

    cfg = ftp_config.get(charger_id)
    if not cfg:
        return web.json_response({'error': 'Unknown charger'}, status=400)

    def ftp_work():
        """Run FTP operations in thread (ftplib is synchronous)"""
        ftp = FTP()
        ftp.connect(cfg['host'], 21, timeout=15)
        ftp.login('anonymous', 'anonymous')
        ftp.cwd(cfg['path'])

        # List all files
        all_files = [f for f in ftp.nlst() if f not in ('.', '..')]

        # Sort by number in filename: ethlog0, ethlog1, ..., ethlog12
        def sort_key(name):
            match = re.search(r'(\d+)', name)
            return int(match.group(1)) if match else 0

        all_files.sort(key=sort_key, reverse=True)  # newest (highest number) first

        # Limit
        if latest > 0:
            all_files = all_files[:latest]

        if not all_files:
            ftp.quit()
            return None, None, 'No files found'

        # Single file → send directly
        if len(all_files) == 1:
            buf = io.BytesIO()
            ftp.retrbinary(f'RETR {all_files[0]}', buf.write)
            ftp.quit()
            return all_files[0], buf.getvalue(), None

        # Multiple files → zip
        zip_buf = io.BytesIO()
        with zipfile.ZipFile(zip_buf, 'w', zipfile.ZIP_DEFLATED) as zf:
            for fname in all_files:
                fbuf = io.BytesIO()
                ftp.retrbinary(f'RETR {fname}', fbuf.write)
                zf.writestr(fname, fbuf.getvalue())
        ftp.quit()

        label = f'latest{latest}' if latest > 0 else 'all'
        zip_name = f'{charger_id}_ethlog_{label}.zip'
        return zip_name, zip_buf.getvalue(), None

    try:
        # Run synchronous FTP in thread to not block event loop
        loop = asyncio.get_event_loop()
        filename, data, error = await loop.run_in_executor(None, ftp_work)

        if error:
            return web.json_response({'error': error}, status=404)

        content_type = 'application/zip' if filename.endswith('.zip') else 'application/octet-stream'

        return web.Response(
            body=data,
            headers={
                'Content-Type': content_type,
                'Content-Disposition': f'attachment; filename="{filename}"'
            }
        )

    except Exception as e:
        logger.error(f"FTP download error ({charger_id}): {e}")
        return web.json_response({'error': str(e)}, status=500)

async def handle_api_command(request):
    """Execute command on charge point"""
    try:
        data = await request.json()
        cp_id = data.get('cp_id')
        command = data.get('command')
        params = data.get('params', {})
        
        if cp_id not in app_state.charge_points:
            return web.json_response({'error': 'Charge Point not found'}, status=404)
        
        cs = app_state.charge_points[cp_id]
        
        # Map command to method
        cmd_map = {
            'remote_start': lambda: cs.cmd_remote_start(
                params.get('id_tag', 'TEST'),
                params.get('connector_id')
            ),
            'remote_stop': lambda: cs.cmd_remote_stop(params.get('transaction_id')),
            'reset': lambda: cs.cmd_reset(params.get('type', 'Soft')),
            'unlock': lambda: cs.cmd_unlock_connector(params.get('connector_id', 1)),
            'availability': lambda: cs.cmd_change_availability(
                params.get('connector_id', 0),
                params.get('type', 'Operative')
            ),
            'get_config': lambda: cs.cmd_get_configuration(
                keys=params.get('keys'),
                mode=params.get('mode', 'standard')
            ),
            'set_config': lambda: cs.cmd_change_configuration_with_save(
                params.get('key'),
                params.get('value')
            ),
            'clear_cache': lambda: cs.cmd_clear_cache(),
            'data_transfer': lambda: cs.cmd_data_transfer(
                params.get('vendor_id', 'TestVendor'),
                params.get('message_id'),
                params.get('data')
            ),
            'trigger': lambda: cs.cmd_trigger_message(
                params.get('message', 'StatusNotification'),
                params.get('connector_id')
            ),
            'reserve': lambda: cs.cmd_reserve_now(
                params.get('connector_id', 1),
                params.get('id_tag', 'RESERVE'),
                params.get('reservation_id', 1),
                params.get('expiry_seconds')
            ),
            'cancel_reserve': lambda: cs.cmd_cancel_reservation(params.get('reservation_id', 1)),
            'set_profile': lambda: cs.cmd_set_charging_profile(
                params.get('connector_id', 1),
                params.get('limit', 10000),
                params.get('purpose'),
                params.get('stack_level', 0),
                params.get('rate_unit', 'W')
            ),
            'clear_profile': lambda: cs.cmd_clear_charging_profile(
                params.get('connector_id'),
                params.get('charging_profile_id'),
                params.get('charging_profile_purpose'),
                params.get('stack_level')
            ),
            'get_composite': lambda: cs.cmd_get_composite_schedule(
                params.get('connector_id', 0),
                params.get('duration', 3600)
            ),
            'get_local_list': lambda: cs.cmd_get_local_list_version(),
            'send_local_list': lambda: cs.cmd_send_local_list(
                params.get('version', 1),
                params.get('type', 'Full'),
                params.get('tags', [])
            ),
            'get_diagnostics': lambda: cs.cmd_get_diagnostics(
                params.get('location', 'ftp://diagnostics.server.com/'),
                params.get('start_time'),
                params.get('stop_time'),
                params.get('retries'),
                params.get('retry_interval')
            ),
        }
        
        if command not in cmd_map:
            return web.json_response({'error': f'Unknown command: {command}'}, status=400)
        
        result = await cmd_map[command]()
        return web.json_response({'success': True, 'result': result})
        
    except Exception as e:
        logger.exception("Command error")
        return web.json_response({'error': str(e)}, status=500)

async def handle_websocket(request):
    """WebSocket for real-time updates to web UI"""
    ws = web.WebSocketResponse()
    await ws.prepare(request)
    
    app_state.web_clients.add(ws)
    logger.info(f"Web client connected ({len(app_state.web_clients)} total)")
    
    # Send initial state: every station this CSMS knows (online, offline and registered-only)
    await ws.send_str(json.dumps({'type': 'init', 'data': {'charge_points': app_state.station_records()}}, default=str))
    
    try:
        async for msg in ws:
            if msg.type == aiohttp.WSMsgType.TEXT:
                pass  # Handle incoming messages if needed
            elif msg.type == aiohttp.WSMsgType.ERROR:
                break
    finally:
        app_state.web_clients.discard(ws)
        logger.info(f"Web client disconnected ({len(app_state.web_clients)} total)")
    
    return ws


# ============================================================================
# RFID Card Management API
# ============================================================================
async def handle_api_rfid_list(request):
    """Get list of all RFID cards"""
    cards = []
    for id_tag, info in app_state.rfid_cards.items():
        cards.append({
            'id_tag': id_tag,
            **info
        })
    return web.json_response(cards)

async def handle_api_rfid_add(request):
    """Add or update RFID card"""
    try:
        data = await request.json()
        id_tag = data.get('id_tag', '').strip().upper()
        
        if not id_tag:
            return web.json_response({'error': 'id_tag is required'}, status=400)
        
        status = data.get('status', 'Accepted')
        if status not in ['Accepted', 'Blocked', 'Expired', 'Invalid', 'ConcurrentTx']:
            return web.json_response({'error': 'Invalid status'}, status=400)
        
        app_state.add_rfid_card(
            id_tag=id_tag,
            status=status,
            expiry_date=data.get('expiry_date'),
            parent_id=data.get('parent_id'),
            description=data.get('description', '')
        )
        
        logger.info(f"RFID card added/updated: {id_tag} ({status})")
        
        return web.json_response({
            'success': True,
            'id_tag': id_tag,
            'status': status
        })
        
    except Exception as e:
        logger.exception("Failed to add RFID card")
        return web.json_response({'error': str(e)}, status=500)

async def handle_api_rfid_delete(request):
    """Delete RFID card"""
    try:
        data = await request.json()
        id_tag = data.get('id_tag', '').strip().upper()
        
        if not id_tag:
            return web.json_response({'error': 'id_tag is required'}, status=400)
        
        if app_state.remove_rfid_card(id_tag):
            logger.info(f"RFID card deleted: {id_tag}")
            return web.json_response({'success': True, 'id_tag': id_tag})
        else:
            return web.json_response({'error': 'Card not found'}, status=404)
        
    except Exception as e:
        logger.exception("Failed to delete RFID card")
        return web.json_response({'error': str(e)}, status=500)

async def handle_api_rfid_import(request):
    """Import RFID cards from JSON"""
    try:
        data = await request.json()
        cards = data.get('cards', [])
        
        imported = 0
        for card in cards:
            id_tag = card.get('id_tag', '').strip().upper()
            if id_tag:
                app_state.add_rfid_card(
                    id_tag=id_tag,
                    status=card.get('status', 'Accepted'),
                    expiry_date=card.get('expiry_date'),
                    parent_id=card.get('parent_id'),
                    description=card.get('description', '')
                )
                imported += 1
        
        logger.info(f"Imported {imported} RFID cards")
        return web.json_response({'success': True, 'imported': imported})
        
    except Exception as e:
        logger.exception("Failed to import RFID cards")
        return web.json_response({'error': str(e)}, status=500)


# ============================================================================
# CP Registration Management API
# ============================================================================
async def handle_api_cp_registrations(request):
    """Get all CP registrations"""
    registrations = []
    for cp_id, status in app_state.cp_registrations.items():
        # Get additional info if CP is connected
        cp_data = app_state.cp_data.get(cp_id)
        registrations.append({
            'cp_id': cp_id,
            'status': status,
            'connected': cp_id in app_state.charge_points,
            'vendor': cp_data.vendor if cp_data else '',
            'model': cp_data.model if cp_data else ''
        })
    
    # Also add currently connected CPs that might not be in registrations
    for cp_id, cs in app_state.charge_points.items():
        if cp_id not in app_state.cp_registrations:
            registrations.append({
                'cp_id': cp_id,
                'status': 'Pending',
                'connected': True,
                'vendor': cs.data.vendor,
                'model': cs.data.model
            })
    
    return web.json_response(registrations)

async def handle_api_cp_set_status(request):
    """Set CP registration status"""
    try:
        data = await request.json()
        cp_id = data.get('cp_id', '').strip()
        status = data.get('status', 'Pending')
        force_disconnect = data.get('force_disconnect', True)  # Default: disconnect on Rejected
        
        if not cp_id:
            return web.json_response({'error': 'cp_id is required'}, status=400)
        
        if status not in ['Accepted', 'Pending', 'Rejected']:
            return web.json_response({'error': 'Invalid status. Must be Accepted, Pending, or Rejected'}, status=400)
        
        app_state.set_cp_registration_status(cp_id, status)

        disconnected = False
        triggered = False

        # Update connected CP if exists
        if cp_id in app_state.charge_points:
            cs = app_state.charge_points[cp_id]
            cs.data.registration_status = status
            await cs._notify_update()
        else:
            # offline / registered-only station: keep the fleet table in sync
            if cp_id in app_state.cp_data:
                app_state.cp_data[cp_id].registration_status = status
            await app_state.broadcast('station_update', app_state.station_record(cp_id))

        if cp_id in app_state.charge_points:
            cs = app_state.charge_points[cp_id]

            if status == 'Pending':
                # OCPP 1.6 §4.2.1: Pending ต้อง "คง connection ไว้" เพื่อให้ server ส่ง config หา CP ได้
                # -> ไม่ตัดสาย แต่สั่ง TriggerMessage(BootNotification) บน connection เดิมแทน
                #    CP จะส่ง BootNotification ใหม่ -> ได้ Pending -> เข้าโหมดรอ config ทันที
                #    โดยไม่หลุดเลยสักวินาที (แก้ปัญหาเดิม: force disconnect ทำให้ server
                #    ส่ง message ระหว่างหน้าต่าง Pending ของ CP ไม่ได้)
                try:
                    logger.info(f"CP {cp_id} status -> Pending: TriggerMessage(BootNotification) on live connection")
                    result = await asyncio.wait_for(cs.cmd_trigger_message('BootNotification'), timeout=10)
                    triggered = True
                    logger.info(f"TriggerMessage(BootNotification) -> {result}")
                except Exception as e:
                    # CP ไม่ตอบ/ไม่รองรับ TriggerMessage -> fallback ตัดสายแบบเดิม
                    # เพื่อให้ CP reconnect มารับสถานะใหม่ผ่าน BootNotification
                    logger.warning(f"TriggerMessage failed for {cp_id}: {e} — falling back to disconnect")
                    if force_disconnect:
                        try:
                            await cs._connection.close(1000, f"Registration status changed to {status}")
                            disconnected = True
                        except Exception as e2:
                            logger.warning(f"Failed to disconnect CP {cp_id}: {e2}")
            elif status == 'Rejected' and force_disconnect:
                # Rejected: ตัดสายตามเดิม (สเปคไม่ให้ CP ที่ถูก reject ค้าง connection ส่ง message)
                try:
                    logger.info(f"Force disconnecting CP {cp_id} due to status change to {status}")
                    # ocpp library stores websocket in _connection attribute
                    await cs._connection.close(1000, f"Registration status changed to {status}")
                    disconnected = True
                except Exception as e:
                    logger.warning(f"Failed to disconnect CP {cp_id}: {e}")

        logger.info(f"CP {cp_id} registration status set to: {status}")

        return web.json_response({
            'success': True,
            'cp_id': cp_id,
            'status': status,
            'disconnected': disconnected,
            'triggered': triggered,
            'message': f'CP will receive {status} status on next BootNotification' +
                      (' (force disconnected)' if disconnected else '') +
                      (' (triggered BootNotification on live connection)' if triggered else '')
        })
        
    except Exception as e:
        logger.exception("Failed to set CP status")
        return web.json_response({'error': str(e)}, status=500)

async def handle_api_cp_delete_registration(request):
    """Delete CP registration"""
    try:
        data = await request.json()
        cp_id = data.get('cp_id', '').strip()
        
        if not cp_id:
            return web.json_response({'error': 'cp_id is required'}, status=400)
        
        if app_state.remove_cp_registration(cp_id):
            logger.info(f"CP registration deleted: {cp_id}")
            if cp_id not in app_state.charge_points:
                app_state.cp_data.pop(cp_id, None)                 # offline station: drop it from the fleet table
                await app_state.broadcast('station_removed', {'id': cp_id})
            else:
                await app_state.broadcast('station_update', app_state.station_record(cp_id))
            return web.json_response({'success': True, 'cp_id': cp_id})
        else:
            return web.json_response({'error': 'CP not found'}, status=404)
        
    except Exception as e:
        logger.exception("Failed to delete CP registration")
        return web.json_response({'error': str(e)}, status=500)


async def handle_api_cp_disconnect(request):
    """Force disconnect a Charge Point"""
    try:
        data = await request.json()
        cp_id = data.get('cp_id', '').strip()
        reason = data.get('reason', 'Requested by operator')
        
        if not cp_id:
            return web.json_response({'error': 'cp_id is required'}, status=400)
        
        if cp_id not in app_state.charge_points:
            return web.json_response({'error': 'CP not connected'}, status=404)
        
        cs = app_state.charge_points[cp_id]
        
        try:
            logger.info(f"Force disconnecting CP {cp_id}: {reason}")
            # ocpp library stores websocket in _connection attribute
            await cs._connection.close(1000, reason)
            return web.json_response({
                'success': True, 
                'cp_id': cp_id,
                'message': f'CP {cp_id} disconnected'
            })
        except Exception as e:
            return web.json_response({'error': f'Failed to disconnect: {e}'}, status=500)
        
    except Exception as e:
        logger.exception("Failed to disconnect CP")
        return web.json_response({'error': str(e)}, status=500)


# ============================================================================
# Default Configuration API
# ============================================================================
async def handle_api_default_config(request):
    """Get default OCPP configuration"""
    config_list = []
    for key, info in app_state.default_config.items():
        config_list.append({
            'key': key,
            'value': info['value'],
            'readonly': info['readonly'],
            'description': info['description']
        })
    return web.json_response(config_list)

async def handle_api_restore_config(request):
    """Restore configuration to default values"""
    try:
        data = await request.json()
        cp_id = data.get('cp_id', '').strip()
        keys = data.get('keys', [])  # List of keys to restore, empty = all writable keys
        
        if not cp_id:
            return web.json_response({'error': 'cp_id is required'}, status=400)
        
        if cp_id not in app_state.charge_points:
            return web.json_response({'error': 'Charge Point not connected'}, status=404)
        
        cs = app_state.charge_points[cp_id]
        results = []
        
        # If no specific keys, restore all writable keys
        if not keys:
            keys = [k for k, v in app_state.default_config.items() if not v['readonly']]
        
        for key in keys:
            if key in app_state.default_config:
                default_info = app_state.default_config[key]
                if not default_info['readonly']:
                    try:
                        result = await cs.cmd_change_configuration(key, default_info['value'])
                        results.append({
                            'key': key,
                            'value': default_info['value'],
                            'status': result.get('status', 'Unknown')
                        })
                    except Exception as e:
                        results.append({
                            'key': key,
                            'value': default_info['value'],
                            'status': f'Error: {str(e)}'
                        })
        
        logger.info(f"Restored {len(results)} config keys for CP {cp_id}")
        
        return web.json_response({
            'success': True,
            'cp_id': cp_id,
            'restored': results
        })
        
    except Exception as e:
        logger.exception("Failed to restore configuration")
        return web.json_response({'error': str(e)}, status=500)

async def handle_api_set_config_batch(request):
    """Set multiple configuration keys at once"""
    try:
        data = await request.json()
        cp_id = data.get('cp_id', '').strip()
        configs = data.get('configs', [])  # List of {key, value}
        
        if not cp_id:
            return web.json_response({'error': 'cp_id is required'}, status=400)
        
        if cp_id not in app_state.charge_points:
            return web.json_response({'error': 'Charge Point not connected'}, status=404)
        
        cs = app_state.charge_points[cp_id]
        results = []
        
        for cfg in configs:
            key = cfg.get('key', '')
            value = cfg.get('value', '')
            if key:
                try:
                    result = await cs.cmd_change_configuration(key, str(value))
                    results.append({
                        'key': key,
                        'value': value,
                        'status': result.get('status', 'Unknown')
                    })
                except Exception as e:
                    results.append({
                        'key': key,
                        'value': value,
                        'status': f'Error: {str(e)}'
                    })
        
        return web.json_response({
            'success': True,
            'cp_id': cp_id,
            'results': results
        })
        
    except Exception as e:
        logger.exception("Failed to set batch configuration")
        return web.json_response({'error': str(e)}, status=500)


