def _db_keep_files() -> bool:
    fn = globals().get('db_keep_files')
    return fn() if fn else True


def _db_load_collection(coll, loader):
    fn = globals().get('db_load_collection')
    return fn(coll, loader) if fn else (loader() or {}, 'json')


def _db_load_doc(coll, key, loader):
    fn = globals().get('db_load_doc')
    return fn(coll, key, loader) if fn else (loader(), 'json')
