def _pay_now() -> str:
    return datetime.now().isoformat(timespec='seconds')


def _pay_deep_merge(base: dict, override: dict) -> dict:
    out = json.loads(json.dumps(base))
    for k, v in (override or {}).items():
        if isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k] = _pay_deep_merge(out[k], v)
        else:
            out[k] = v
    return out


def _pay_money(x) -> float:
    try:
        return round(float(x) + 1e-9, 2)
    except (TypeError, ValueError):
        return 0.0


def pay_cost(tariff: dict, kwh: float, minutes: float) -> float:
    """Cost of a session in the configured tariff (session fee + energy + time)."""
    return _pay_money(float(tariff.get('session_fee') or 0) + max(0.0, kwh) * float(tariff.get('per_kwh') or 0)
                      + max(0.0, minutes) * float(tariff.get('per_minute') or 0))


def pay_budget(tariff: dict, amount: float) -> dict:
    """What a prepaid amount buys (shown to the customer before paying)."""
    net = max(0.0, float(amount) - float(tariff.get('session_fee') or 0))
    per_kwh = float(tariff.get('per_kwh') or 0)
    per_min = float(tariff.get('per_minute') or 0)
    return {
        'kwh': round(net / per_kwh, 2) if per_kwh > 0 and per_min <= 0 else None,
        'minutes': round(net / per_min) if per_min > 0 and per_kwh <= 0 else None,
        'mixed': per_kwh > 0 and per_min > 0,
    }


# ---------------------------------------------------------------------------
# Settings
# ---------------------------------------------------------------------------
class PaymentSettings:
    def __init__(self):
        self.data = json.loads(json.dumps(PAY_DEFAULT_SETTINGS))
        self.load()

    def load(self):
        def from_file():
            try:
                if os.path.exists(PAY_SETTINGS_FILE):
                    with open(PAY_SETTINGS_FILE, 'r', encoding='utf-8') as f:
                        return json.load(f)
            except Exception as e:
                logger.error(f"payment: failed to load {PAY_SETTINGS_FILE}: {e}")
            return None
        saved, _src = _db_load_doc('settings', 'payment', from_file)
        if isinstance(saved, dict) and saved:
            self.data = _pay_deep_merge(PAY_DEFAULT_SETTINGS, saved)
        if not self.data.get('webhook_secret'):
            self.data['webhook_secret'] = secrets.token_urlsafe(24)
            self.save()

    def save(self, force_files: bool = False):
        db = _db()
        if db is not None:
            try:
                db.put_doc('settings', 'payment', self.data)
            except Exception as e:
                logger.error(f"payment: database save failed: {e}")
        if db is None or force_files or _db_keep_files():
            try:
                tmp = PAY_SETTINGS_FILE + '.tmp'
                with open(tmp, 'w', encoding='utf-8') as f:
                    json.dump(self.data, f, indent=2, ensure_ascii=False)
                os.replace(tmp, PAY_SETTINGS_FILE)
            except Exception as e:
                logger.error(f"payment: failed to save {PAY_SETTINGS_FILE}: {e}")

    def update(self, changes: dict) -> dict:
        """Validate + merge a settings change coming from the Payments tab."""
        merged = _pay_deep_merge(self.data, changes or {})
        t = merged.setdefault('tariff', {})
        for k in ('per_kwh', 'per_minute', 'session_fee', 'min_amount', 'max_amount', 'refund_threshold'):
            try:
                t[k] = max(0.0, float(t.get(k) or 0))
            except (TypeError, ValueError):
                t[k] = PAY_DEFAULT_SETTINGS['tariff'][k]
        if t['max_amount'] < t['min_amount']:
            t['max_amount'] = t['min_amount']
        presets = []
        for p in (t.get('presets') or []):
            try:
                v = float(p)
                if v > 0:
                    presets.append(int(v) if v == int(v) else v)
            except (TypeError, ValueError):
                continue
        t['presets'] = presets[:8] or PAY_DEFAULT_SETTINGS['tariff']['presets']
        merged['currency'] = (str(merged.get('currency') or 'BTN').strip().upper() or 'BTN')[:3]
        merged['currency_symbol'] = str(merged.get('currency_symbol') or 'Nu.').strip()[:6]
        merged['currency_num'] = (str(merged.get('currency_num') or '064').strip() or '064')[:3]
        if not merged.get('webhook_secret'):
            merged['webhook_secret'] = self.data.get('webhook_secret') or secrets.token_urlsafe(24)
        for mid, m in merged.get('methods', {}).items():
            if mid not in PAY_GATEWAYS:
                continue
            m['enabled'] = bool(m.get('enabled'))
        self.data = merged
        self.save()
        return self.data

    @property
    def tariff(self) -> dict:
        return self.data.get('tariff', {})

    def method(self, mid: str) -> dict:
        return (self.data.get('methods') or {}).get(mid, {}) or {}

    def enabled_methods(self) -> list:
        return [mid for mid in ('demo', 'rma_bfs', 'bhutan_qr') if self.method(mid).get('enabled') and mid in PAY_GATEWAYS]

    def public(self) -> dict:
        """What the customer page needs (no secrets)."""
        methods = []
        for mid in self.enabled_methods():
            gw = PAY_GATEWAYS[mid]
            methods.append(gw.customer_info(self.method(mid), self))
        return {
            'enabled': bool(self.data.get('enabled', True)),
            'currency': self.data.get('currency', 'BTN'),
            'symbol': self.data.get('currency_symbol', 'Nu.'),
            'tariff': {k: self.tariff.get(k) for k in ('per_kwh', 'per_minute', 'session_fee', 'min_amount', 'max_amount', 'presets')},
            'methods': methods,
            'brand': BRAND_NAME,
            'merchant': self.data.get('merchant_name', ''),
            'public_station_list': bool(self.data.get('public_station_list')),
        }

    def admin(self) -> dict:
        d = json.loads(json.dumps(self.data))
        rb = d.get('methods', {}).get('rma_bfs', {})
        for k in ('private_key_pem', 'bfs_public_pem'):
            if rb.get(k):
                rb[k + '_set'] = True
                rb[k] = ''                                   # never send the key back to the browser
        d['bfs_fields'] = PAY_BFS_FIELDS
        d['banks_default'] = [[c, n, a] for c, n, a in PAY_BANKS_BT]
        return d


# ---------------------------------------------------------------------------
# Ledger
# ---------------------------------------------------------------------------
class PaymentLedger:
    PUBLIC_FIELDS = ('ref', 'cp_id', 'connector_id', 'amount', 'currency', 'symbol', 'method', 'method_name', 'state',
                     'state_detail', 'tariff', 'budget', 'transaction_id', 'started_at', 'stopped_at', 'used_kwh',
                     'used_minutes', 'used_amount', 'remaining_amount', 'refund', 'created_at', 'paid_at', 'updated_at',
                     'expires_at', 'stop_reason', 'auto_stopped', 'customer_message', 'next', 'public_data', 'source',
                     'kind', 'discount')

    def __init__(self):
        self.records: Dict[str, dict] = {}
        self._dirty = False
        self._last_save = 0.0
        self.load()

    # ---- persistence
    def load(self):
        def from_file():
            try:
                if os.path.exists(PAY_LEDGER_FILE):
                    with open(PAY_LEDGER_FILE, 'r', encoding='utf-8') as f:
                        data = json.load(f)
                    return {r['ref']: r for r in (data.get('records') or []) if isinstance(r, dict) and r.get('ref')}
            except Exception as e:
                logger.error(f"payment: failed to load {PAY_LEDGER_FILE}: {e}")
            return {}
        self.records, src = _db_load_collection('payments', from_file)
        self.records = {k: v for k, v in self.records.items() if isinstance(v, dict) and v.get('ref')}
        logger.info(f"payment: loaded {len(self.records)} payment records ({src})")
        # sessions that were mid-flight when the CSMS stopped cannot be resumed reliably
        for r in self.records.values():
            if r.get('state') in ('created', 'awaiting'):
                r['state'] = 'expired'
                r['state_detail'] = 'CSMS restarted before the payment was completed'
            elif r.get('state') in ('starting', 'stopping'):
                r['state'] = 'charging' if r.get('transaction_id') else 'paid'

    def save(self, force: bool = False):
        self._dirty = True
        now = time.time()
        if not force and now - self._last_save < 2.0:
            return
        self.flush()

    def flush(self, force_files: bool = False):
        if not self._dirty and not force_files:
            return
        try:
            recs = sorted(self.records.values(), key=lambda r: r.get('created_at', ''))
            if len(recs) > PAY_MAX_RECORDS:
                keep = [r for r in recs if r.get('state') in PAY_ACTIVE_STATES]
                done = [r for r in recs if r.get('state') not in PAY_ACTIVE_STATES]
                recs = done[-(PAY_MAX_RECORDS - len(keep)):] + keep if PAY_MAX_RECORDS > len(keep) else keep
                self.records = {r['ref']: r for r in recs}
            db = _db()
            if db is not None:
                db.sync_collection('payments', self.records)      # [DB] only the changed records are written
            if db is None or force_files or _db_keep_files():
                tmp = PAY_LEDGER_FILE + '.tmp'
                with open(tmp, 'w', encoding='utf-8') as f:
                    json.dump({'records': recs}, f, indent=1, ensure_ascii=False, default=str)
                os.replace(tmp, PAY_LEDGER_FILE)
            self._dirty = False
            self._last_save = time.time()
        except Exception as e:
            logger.error(f"payment: failed to save {PAY_LEDGER_FILE}: {e}")

    # ---- records
    def new_ref(self) -> str:
        while True:
            ref = (PAYMENT_IDTAG_PREFIX + secrets.token_hex(6).upper())[:20]
            if ref not in self.records:
                return ref

    def create(self, cp_id: str, connector_id: int, amount: float, method: str, settings: 'PaymentSettings',
               source: str = 'csms', customer: dict = None, ref: str = None, extra: dict = None) -> dict:
        tariff = {k: settings.tariff.get(k) for k in ('per_kwh', 'per_minute', 'session_fee', 'refund_threshold')}
        now = _pay_now()
        rec = {
            'ref': ref or self.new_ref(),
            'token': secrets.token_urlsafe(12),
            'cp_id': cp_id, 'connector_id': int(connector_id or 0),
            'amount': _pay_money(amount), 'currency': settings.data.get('currency', 'BTN'),
            'symbol': settings.data.get('currency_symbol', 'Nu.'),
            'method': method, 'method_name': PAY_GATEWAYS[method].name if method in PAY_GATEWAYS else method,
            'state': 'created', 'state_detail': '', 'next': '',
            'tariff': tariff, 'budget': pay_budget(tariff, amount),
            'gateway': {}, 'public_data': {},
            'transaction_id': None, 'meter_start': None, 'started_at': '', 'stopped_at': '', 'stop_reason': '',
            'used_kwh': 0.0, 'used_minutes': 0.0, 'used_amount': 0.0, 'remaining_amount': _pay_money(amount),
            'auto_stopped': False, 'start_attempts': 0, 'last_start_at': '', 'stop_sent_at': '',
            'refund': {'status': 'none', 'amount': 0.0, 'ref': '', 'at': ''},
            'customer': customer or {}, 'customer_message': '', 'notes': [],
            'source': source, 'created_at': now, 'paid_at': '', 'updated_at': now,
            'expires_at': (datetime.now() + timedelta(seconds=PAY_UNPAID_TTL)).isoformat(timespec='seconds'),
            'kind': 'charge', 'customer_id': '', 'discount': None,
        }
        if extra:
            rec.update(extra)
        self.records[rec['ref']] = rec
        self.save(force=True)
        return rec

    def touch(self, rec: dict, force: bool = True, **changes):
        rec.update(changes)
        rec['updated_at'] = _pay_now()
        self.save(force=force)

    def note(self, rec: dict, text: str):
        rec.setdefault('notes', []).append({'at': _pay_now(), 'text': str(text)[:300]})
        rec['notes'] = rec['notes'][-30:]

    def get(self, ref: str) -> Optional[dict]:
        return self.records.get(str(ref or '').strip().upper())

    def find_by_txn(self, cp_id: str, transaction_id) -> Optional[dict]:
        if transaction_id is None:
            return None
        for r in self.records.values():
            if r.get('cp_id') == cp_id and r.get('transaction_id') == transaction_id and r.get('state') in PAY_ACTIVE_STATES:
                return r
        return None

    def find_by_idtag(self, id_tag: str) -> Optional[dict]:
        return self.records.get(str(id_tag or '').strip().upper())

    def active_for_connector(self, cp_id: str, connector_id: int) -> Optional[dict]:
        best = None
        for r in self.records.values():
            if r.get('cp_id') == cp_id and int(r.get('connector_id') or 0) == int(connector_id or 0) \
                    and r.get('state') in ('paid', 'starting', 'charging', 'stopping'):
                if best is None or r.get('created_at', '') > best.get('created_at', ''):
                    best = r
        return best

    def charging(self) -> list:
        return [r for r in self.records.values() if r.get('state') in ('charging', 'stopping')]

    def public_view(self, rec: dict) -> dict:
        return {k: rec.get(k) for k in self.PUBLIC_FIELDS}

    def admin_view(self, rec: dict) -> dict:
        d = dict(rec)
        d.pop('token', None)
        gw = dict(d.get('gateway') or {})
        for k in ('otp', 'account_no'):
            gw.pop(k, None)
        d['gateway'] = gw
        return d

    def kpis(self) -> dict:
        today = datetime.now().strftime('%Y-%m-%d')
        out = {'today_revenue': 0.0, 'today_sessions': 0, 'awaiting': 0, 'charging': 0, 'refund_due': 0,
               'refund_due_amount': 0.0, 'paid_not_started': 0, 'total': len(self.records)}
        out['today_topups'] = 0.0
        for r in self.records.values():
            st = r.get('state')
            if r.get('kind') == 'topup':
                if (r.get('paid_at') or '').startswith(today) and st == 'completed':
                    out['today_topups'] += float(r.get('amount') or 0)
                if st in ('awaiting', 'created'):
                    out['awaiting'] += 1
                continue
            if st in ('awaiting', 'created'):
                out['awaiting'] += 1
            elif st in ('charging', 'stopping', 'starting'):
                out['charging'] += 1
            elif st == 'paid':
                out['paid_not_started'] += 1
            if (r.get('refund') or {}).get('status') == 'due':
                out['refund_due'] += 1
                out['refund_due_amount'] += float((r.get('refund') or {}).get('amount') or 0)
            if (r.get('paid_at') or '').startswith(today) and st not in ('cancelled', 'expired', 'failed'):
                out['today_sessions'] += 1
                out['today_revenue'] += float(r.get('used_amount') or 0) if st == 'completed' else float(r.get('amount') or 0)
        out['today_revenue'] = _pay_money(out['today_revenue'])
        out['today_topups'] = _pay_money(out['today_topups'])
        out['refund_due_amount'] = _pay_money(out['refund_due_amount'])
        return out


# ---------------------------------------------------------------------------
# RSA (SHA1withRSA, PKCS#1 v1.5) for the RMA / BFS gateway checksum. Uses "cryptography" when it is
# installed, otherwise a small pure-Python implementation (PEM -> DER -> RSA key).
# ---------------------------------------------------------------------------
_PAY_SHA1_DIGESTINFO = bytes.fromhex('3021300906052b0e03021a05000414')


def _pay_der_items(data: bytes, pos: int = 0, end: int = None):
    """Yield (tag, value_bytes, next_pos) for the DER elements between pos and end."""
    end = len(data) if end is None else end
    while pos < end:
        tag = data[pos]
        pos += 1
        length = data[pos]
        pos += 1
        if length & 0x80:
            n = length & 0x7F
            length = int.from_bytes(data[pos:pos + n], 'big')
            pos += n
        yield tag, data[pos:pos + length], pos + length
        pos += length


def _pay_pem_to_der(pem: str) -> tuple:
    m = _pay_re.search(r'-----BEGIN ([A-Z ]+)-----(.*?)-----END ', pem or '', _pay_re.S)
    if not m:
        raise ValueError('not a PEM block')
    return m.group(1).strip(), _pay_b64.b64decode(''.join(m.group(2).split()))


def _pay_rsa_private_numbers(pem: str) -> tuple:
    kind, der = _pay_pem_to_der(pem)
    tag, seq, _ = next(_pay_der_items(der))
    items = list(_pay_der_items(seq))
    if kind == 'PRIVATE KEY':                                   # PKCS#8: version, algorithm, OCTET STRING(PKCS#1)
        _, inner, _ = items[2]
        tag, seq, _ = next(_pay_der_items(inner))
        items = list(_pay_der_items(seq))
    ints = [int.from_bytes(v, 'big') for t, v, _ in items if t == 0x02]
    if len(ints) < 4:
        raise ValueError('unsupported private key format')
    return ints[1], ints[3]                                     # n, d


def _pay_rsa_public_numbers(pem: str) -> tuple:
    kind, der = _pay_pem_to_der(pem)
    if kind == 'RSA PUBLIC KEY':
        tag, seq, _ = next(_pay_der_items(der))
        ints = [int.from_bytes(v, 'big') for t, v, _ in _pay_der_items(seq) if t == 0x02]
        return ints[0], ints[1]
    # PUBLIC KEY (SubjectPublicKeyInfo) or CERTIFICATE: find the BIT STRING that follows the rsaEncryption OID
    rsa_oid = bytes.fromhex('2a864886f70d010101')

    def walk(blob: bytes):
        for tag, val, _ in _pay_der_items(blob):
            if tag == 0x30:                                     # SEQUENCE: AlgorithmIdentifier + BIT STRING ?
                sub = list(_pay_der_items(val))
                if len(sub) == 2 and sub[0][0] == 0x30 and sub[1][0] == 0x03 and rsa_oid in sub[0][1]:
                    bits = sub[1][1][1:]                        # skip the unused-bits byte
                    t2, s2, _ = next(_pay_der_items(bits))
                    ints = [int.from_bytes(v, 'big') for t, v, _ in _pay_der_items(s2) if t == 0x02]
                    return ints[0], ints[1]
                found = walk(val)
                if found:
                    return found
        return None

    found = walk(der)
    if not found:
        raise ValueError('no RSA public key found')
    return found


def pay_rsa_sign_sha1(private_pem: str, data: bytes) -> bytes:
    try:
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import padding
        key = serialization.load_pem_private_key(private_pem.encode(), password=None)
        return key.sign(data, padding.PKCS1v15(), hashes.SHA1())
    except ImportError:
        pass
    n, d = _pay_rsa_private_numbers(private_pem)
    k = (n.bit_length() + 7) // 8
    t = _PAY_SHA1_DIGESTINFO + _pay_hashlib.sha1(data).digest()
    em = b'\x00\x01' + b'\xff' * (k - len(t) - 3) + b'\x00' + t
    return pow(int.from_bytes(em, 'big'), d, n).to_bytes(k, 'big')


def pay_rsa_verify_sha1(public_pem: str, data: bytes, signature: bytes) -> bool:
    try:
        from cryptography import x509
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import padding
        if 'CERTIFICATE' in public_pem:
            key = x509.load_pem_x509_certificate(public_pem.encode()).public_key()
        else:
            key = serialization.load_pem_public_key(public_pem.encode())
        try:
            key.verify(signature, data, padding.PKCS1v15(), hashes.SHA1())
            return True
        except Exception:
            return False
    except ImportError:
        pass
    n, e = _pay_rsa_public_numbers(public_pem)
    k = (n.bit_length() + 7) // 8
    if len(signature) != k:
        return False
    em = pow(int.from_bytes(signature, 'big'), e, n).to_bytes(k, 'big')
    t = _PAY_SHA1_DIGESTINFO + _pay_hashlib.sha1(data).digest()
    return em == b'\x00\x01' + b'\xff' * (k - len(t) - 3) + b'\x00' + t


# ---------------------------------------------------------------------------
# Gateways
# ---------------------------------------------------------------------------
class PayGateway:
    id = 'base'
    name = 'Gateway'
    kind = 'account'                       # account (bank + OTP) | qr | manual

    def customer_info(self, cfg: dict, settings: 'PaymentSettings') -> dict:
        return {'id': self.id, 'name': cfg.get('name') or self.name, 'kind': self.kind}

    async def begin(self, rec: dict, cfg: dict, params: dict, settings: 'PaymentSettings') -> dict:
        raise NotImplementedError

    async def confirm(self, rec: dict, cfg: dict, params: dict, settings: 'PaymentSettings') -> dict:
        return {'ok': False, 'error': 'nothing to confirm'}

    async def cancel(self, rec: dict, cfg: dict, settings: 'PaymentSettings') -> None:
        return None

    async def refund(self, rec: dict, cfg: dict, amount: float, settings: 'PaymentSettings') -> dict:
        return {'status': 'due'}           # no refund API: the operator refunds by hand


def _pay_bank_list(cfg: dict) -> list:
    banks = cfg.get('banks') or []
    out = []
    for b in banks:
        if isinstance(b, (list, tuple)) and len(b) >= 2:
            out.append({'code': str(b[0]), 'name': str(b[1]), 'app': str(b[2]) if len(b) > 2 else ''})
        elif isinstance(b, dict) and b.get('code'):
            out.append({'code': str(b['code']), 'name': str(b.get('name') or b['code']), 'app': str(b.get('app') or '')})
    return out or [{'code': c, 'name': n, 'app': a} for c, n, a in PAY_BANKS_BT]


def _pay_valid_account(acc: str) -> bool:
    return bool(_pay_re.fullmatch(r'[0-9]{6,20}', str(acc or '').replace(' ', '').replace('-', '')))


class DemoBankGateway(PayGateway):
    """Simulated bank for classrooms: pick a bank, type an account number, type the OTP shown on the screen."""
    id = 'demo'
    name = 'Demo bank (training)'
    kind = 'account'

    def customer_info(self, cfg, settings):
        d = super().customer_info(cfg, settings)
        d['banks'] = _pay_bank_list(cfg)
        d['demo'] = True
        return d

    async def begin(self, rec, cfg, params, settings):
        bank = str(params.get('bank') or '').upper()
        acc = str(params.get('account') or '').replace(' ', '')
        banks = {b['code']: b for b in _pay_bank_list(cfg)}
        if bank not in banks:
            return {'ok': False, 'error': 'Choose your bank'}
        if not _pay_valid_account(acc):
            return {'ok': False, 'error': 'Enter a valid account number (6-20 digits)'}
        otp = ''.join(_pay_random.choice('0123456789') for _ in range(6))
        rec['gateway'] = {'bank': bank, 'bank_name': banks[bank]['name'], 'account_masked': '****' + acc[-4:],
                          'account_no': acc, 'otp': otp, 'otp_attempts': 0, 'txn_id': 'DEMO' + secrets.token_hex(4).upper()}
        rec['public_data'] = {'bank': banks[bank]['name'], 'account_masked': '****' + acc[-4:],
                              'otp_hint': otp if cfg.get('otp_mode', 'show') == 'show' else ''}
        rec['customer_message'] = 'Demo bank: the OTP that a real bank would send by SMS is shown here.'
        return {'ok': True, 'state': 'awaiting', 'next': 'otp'}

    async def confirm(self, rec, cfg, params, settings):
        gw = rec.setdefault('gateway', {})
        otp = str(params.get('otp') or '').strip()
        if not _pay_re.fullmatch(r'[0-9]{6}', otp):
            return {'ok': False, 'error': 'Enter the 6-digit OTP'}
        gw['otp_attempts'] = int(gw.get('otp_attempts') or 0) + 1
        if not _pay_hmac.compare_digest(otp, str(gw.get('otp') or '')):
            if gw['otp_attempts'] >= PAY_OTP_ATTEMPTS:
                return {'ok': False, 'error': 'Too many wrong OTPs - payment cancelled', 'fatal': True}
            return {'ok': False, 'error': 'Wrong OTP (%d of %d)' % (gw['otp_attempts'], PAY_OTP_ATTEMPTS)}
        gw['auth_no'] = 'DEMO-' + secrets.token_hex(3).upper()
        gw['paid_at'] = _pay_now()
        return {'ok': True, 'state': 'paid', 'paid_ref': gw['auth_no']}

    async def refund(self, rec, cfg, amount, settings):
        return {'status': 'done', 'ref': 'DEMO-RF-' + secrets.token_hex(3).upper(), 'note': 'simulated refund to the same account'}


class RmaBfsGateway(PayGateway):
    """RMA / BFS Payment Gateway (Royal Monetary Authority of Bhutan): pay from a bank account with an OTP.

    Message flow (merchant <-> BFS):  AR authorization request (amount, order no) -> AE account enquiry
    (customer's bank + account, BFS sends the OTP by SMS) -> DR debit request (OTP) -> debit auth code.
    Every message carries a checksum: SHA1withRSA over the field values (sorted by field name, "|" joined)
    signed with the merchant's private key; BFS signs its responses with its own key.
    The exact URL, field names and bank codes come from the RMA integration document given at merchant
    registration - they are configurable (endpoint, field_map, banks).  sandbox=true runs the same flow
    against a local simulation so the customer page can be demonstrated without RMA credentials.
    """
    id = 'rma_bfs'
    name = 'Bank account (RMA Payment Gateway)'
    kind = 'account'

    def fields(self, cfg: dict) -> dict:
        f = dict(PAY_BFS_FIELDS)
        f.update({k: str(v) for k, v in (cfg.get('field_map') or {}).items() if k in f and v})
        return f

    def customer_info(self, cfg, settings):
        d = super().customer_info(cfg, settings)
        d['banks'] = _pay_bank_list(cfg)
        d['sandbox'] = bool(cfg.get('sandbox', True))
        d['demo'] = bool(cfg.get('sandbox', True))
        return d

    def checksum(self, cfg: dict, msg: dict) -> str:
        f = self.fields(cfg)
        values = [str(v) for k, v in sorted(msg.items()) if k != f['checkSum']]
        data = '|'.join(values).encode('utf-8')
        pem = cfg.get('private_key_pem') or ''
        if not pem:
            raise ValueError('merchant private key (PEM) is not configured')
        return pay_rsa_sign_sha1(pem, data).hex().upper()

    def verify(self, cfg: dict, msg: dict) -> bool:
        f = self.fields(cfg)
        pem = cfg.get('bfs_public_pem') or ''
        sig = msg.get(f['checkSum'])
        if not pem or not sig:
            return not pem                                   # nothing to verify against -> accept (logged)
        values = [str(v) for k, v in sorted(msg.items()) if k != f['checkSum']]
        try:
            return pay_rsa_verify_sha1(pem, '|'.join(values).encode('utf-8'), bytes.fromhex(sig))
        except Exception as e:
            logger.warning(f"payment: BFS response signature check failed: {e}")
            return False

    async def post(self, cfg: dict, msg: dict) -> dict:
        """POST a BFS message (form encoded) and parse the answer (form encoded or JSON)."""
        url = cfg.get('endpoint') or ''
        if not url:
            raise ValueError('RMA gateway endpoint URL is not configured')
        timeout = aiohttp.ClientTimeout(total=float(cfg.get('timeout') or 30))
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.post(url, data=msg) as resp:
                text = await resp.text()
        text = text.strip()
        try:
            data = json.loads(text)
            if isinstance(data, dict):
                return data
        except ValueError:
            pass
        return {k: v[0] if isinstance(v, list) and v else v for k, v in _pay_urlparse.parse_qs(text, keep_blank_values=True).items()}

    async def begin(self, rec, cfg, params, settings):
        f = self.fields(cfg)
        bank = str(params.get('bank') or '').upper()
        acc = str(params.get('account') or '').replace(' ', '')
        banks = {b['code']: b for b in _pay_bank_list(cfg)}
        if bank not in banks:
            return {'ok': False, 'error': 'Choose your bank'}
        if not _pay_valid_account(acc):
            return {'ok': False, 'error': 'Enter a valid account number (6-20 digits)'}
        sandbox = bool(cfg.get('sandbox', True))
        gw = {'bank': bank, 'bank_name': banks[bank]['name'], 'account_masked': '****' + acc[-4:], 'account_no': acc,
              'otp_attempts': 0, 'sandbox': sandbox, 'trace': []}
        rec['gateway'] = gw
        order_no = rec['ref'].replace('-', '')[:20]
        if sandbox:
            gw['txn_id'] = 'BFS' + secrets.token_hex(5).upper()
            gw['otp'] = ''.join(_pay_random.choice('0123456789') for _ in range(6))
            gw['trace'].append({'at': _pay_now(), 'msg': 'AR/AE simulated (sandbox)'})
            rec['public_data'] = {'bank': banks[bank]['name'], 'account_masked': '****' + acc[-4:], 'otp_hint': gw['otp'], 'sandbox': True}
            rec['customer_message'] = 'Sandbox: the OTP that BFS would send by SMS is shown here.'
            return {'ok': True, 'state': 'awaiting', 'next': 'otp'}
        # --- live: AR (authorization request)
        ar = {f['msgType']: 'AR', f['benfId']: cfg.get('benf_id') or '', f['benfTxnTime']: datetime.now().strftime('%Y%m%d%H%M%S'),
              f['orderNo']: order_no, f['benfBankCode']: cfg.get('benf_bank_code') or '', f['txnCurrency']: rec['currency'],
              f['txnAmount']: '%.2f' % float(rec['amount']), f['remitterEmail']: cfg.get('remitter_email') or '',
              f['paymentDesc']: ('EV charging %s C%s' % (rec['cp_id'], rec['connector_id']))[:50], f['version']: cfg.get('version') or '1.0'}
        try:
            ar[f['checkSum']] = self.checksum(cfg, ar)
            resp = await self.post(cfg, ar)
        except Exception as e:
            return {'ok': False, 'error': 'Gateway error (AR): %s' % e, 'fatal': True}
        gw['trace'].append({'at': _pay_now(), 'req': 'AR', 'resp': resp})
        code = str(resp.get(f['responseCode']) or resp.get(f['debitAuthCode']) or '')
        txn_id = resp.get(f['bfsTxnId'])
        if not txn_id or (code and code != '00'):
            return {'ok': False, 'error': 'Gateway declined (AR %s: %s)' % (code or '?', resp.get(f['responseDesc']) or ''), 'fatal': True}
        if not self.verify(cfg, resp):
            return {'ok': False, 'error': 'Gateway response signature invalid (AR)', 'fatal': True}
        gw['txn_id'] = str(txn_id)
        # --- live: AE (account enquiry -> BFS sends the OTP)
        ae = {f['msgType']: 'AE', f['bfsTxnId']: gw['txn_id'], f['benfId']: cfg.get('benf_id') or '',
              f['remitterBankId']: bank, f['remitterAccNo']: acc}
        try:
            ae[f['checkSum']] = self.checksum(cfg, ae)
            resp = await self.post(cfg, ae)
        except Exception as e:
            return {'ok': False, 'error': 'Gateway error (AE): %s' % e, 'fatal': True}
        gw['trace'].append({'at': _pay_now(), 'req': 'AE', 'resp': resp})
        code = str(resp.get(f['responseCode']) or resp.get(f['debitAuthCode']) or '00')
        if code != '00':
            return {'ok': False, 'error': 'Account enquiry failed (%s: %s)' % (code, resp.get(f['responseDesc']) or ''), 'fatal': True}
        rec['public_data'] = {'bank': banks[bank]['name'], 'account_masked': '****' + acc[-4:], 'sandbox': False}
        rec['customer_message'] = 'An OTP has been sent to the mobile number registered with your bank.'
        return {'ok': True, 'state': 'awaiting', 'next': 'otp'}

    async def confirm(self, rec, cfg, params, settings):
        f = self.fields(cfg)
        gw = rec.setdefault('gateway', {})
        otp = str(params.get('otp') or '').strip()
        if not _pay_re.fullmatch(r'[0-9]{4,8}', otp):
            return {'ok': False, 'error': 'Enter the OTP'}
        gw['otp_attempts'] = int(gw.get('otp_attempts') or 0) + 1
        if gw.get('sandbox'):
            if not _pay_hmac.compare_digest(otp, str(gw.get('otp') or '')):
                if gw['otp_attempts'] >= PAY_OTP_ATTEMPTS:
                    return {'ok': False, 'error': 'Too many wrong OTPs - payment cancelled', 'fatal': True}
                return {'ok': False, 'error': 'Wrong OTP (%d of %d)' % (gw['otp_attempts'], PAY_OTP_ATTEMPTS)}
            gw['auth_no'] = 'SBX-' + secrets.token_hex(3).upper()
            gw['paid_at'] = _pay_now()
            gw.setdefault('trace', []).append({'at': _pay_now(), 'msg': 'DR simulated (sandbox) -> 00'})
            return {'ok': True, 'state': 'paid', 'paid_ref': gw['auth_no']}
        dr = {f['msgType']: 'DR', f['bfsTxnId']: gw.get('txn_id') or '', f['benfId']: cfg.get('benf_id') or '', f['remitterOtp']: otp}
        try:
            dr[f['checkSum']] = self.checksum(cfg, dr)
            resp = await self.post(cfg, dr)
        except Exception as e:
            return {'ok': False, 'error': 'Gateway error (DR): %s' % e, 'fatal': True}
        gw.setdefault('trace', []).append({'at': _pay_now(), 'req': 'DR', 'resp': resp})
        code = str(resp.get(f['debitAuthCode']) or resp.get(f['responseCode']) or '')
        if code != '00':
            fatal = gw['otp_attempts'] >= PAY_OTP_ATTEMPTS
            return {'ok': False, 'error': 'Debit failed (%s: %s)' % (code or '?', resp.get(f['responseDesc']) or ''), 'fatal': fatal}
        if not self.verify(cfg, resp):
            return {'ok': False, 'error': 'Gateway response signature invalid (DR)', 'fatal': True}
        gw['auth_no'] = str(resp.get(f['debitAuthNo']) or '')
        gw['paid_at'] = _pay_now()
        return {'ok': True, 'state': 'paid', 'paid_ref': gw['auth_no']}


class BhutanQrGateway(PayGateway):
    """Bhutan QR (EMVCo merchant-presented QR of the RMA national QR scheme).

    The CSMS turns the merchant QR issued by the bank (static_payload) into a dynamic QR per session:
    tag 01 = 12, tag 53 = currency, tag 54 = amount, tag 62 = payment reference, fresh CRC.  Any Bhutan QR
    enabled banking app pays it.  The gateway has no API that tells the CSMS about the credit, so the
    payment is confirmed by the operator (Payments tab), by the bank's notification webhook, or - for
    training - by the customer's own confirmation (confirm_mode = customer).
    """
    id = 'bhutan_qr'
    name = 'Bhutan QR'
    kind = 'qr'

    def customer_info(self, cfg, settings):
        d = super().customer_info(cfg, settings)
        d['instructions'] = cfg.get('instructions') or ''
        d['confirm_mode'] = cfg.get('confirm_mode') or 'operator'
        d['configured'] = bool(cfg.get('static_payload') or (cfg.get('account_tag') and cfg.get('account_value')))
        d['apps'] = [a for _, _, a in PAY_BANKS_BT if a]
        return d

    def payload(self, cfg: dict, settings: 'PaymentSettings', amount: float, ref: str) -> str:
        static = (cfg.get('static_payload') or '').strip()
        if not static and cfg.get('account_tag') and cfg.get('account_value'):
            static = emv_static_payload(str(cfg['account_tag']), str(cfg['account_value']), settings.data.get('merchant_name') or 'EV CHARGING',
                                        settings.data.get('merchant_city') or 'THIMPHU', cfg.get('mcc') or '5552',
                                        settings.data.get('currency_num') or '064')
        if not static:
            # no merchant QR configured yet: a clearly marked placeholder so the flow can be trained
            static = emv_static_payload('26', emv_tlv('00', 'bt.rma.qr.demo') + emv_tlv('01', 'DEMO-MERCHANT'),
                                        settings.data.get('merchant_name') or 'EV CHARGING', settings.data.get('merchant_city') or 'THIMPHU',
                                        cfg.get('mcc') or '5552', settings.data.get('currency_num') or '064')
        return emv_dynamic_payload(static, amount, ref, settings.data.get('currency_num') or '064', 'EV charging',
                                   settings.data.get('merchant_name') or '', settings.data.get('merchant_city') or '')

    async def begin(self, rec, cfg, params, settings):
        try:
            payload = self.payload(cfg, settings, rec['amount'], rec['ref'])
        except Exception as e:
            return {'ok': False, 'error': 'Bhutan QR is not configured correctly: %s' % e, 'fatal': True}
        svg = QrCode.encode(payload, 'M').to_svg(scale=6, border=3)
        rec['gateway'] = {'payload': payload, 'confirm_mode': cfg.get('confirm_mode') or 'operator', 'claimed': False}
        rec['public_data'] = {'qr_svg': svg, 'payload': payload, 'confirm_mode': cfg.get('confirm_mode') or 'operator',
                              'configured': bool(cfg.get('static_payload') or (cfg.get('account_tag') and cfg.get('account_value')))}
        rec['customer_message'] = cfg.get('instructions') or ''
        return {'ok': True, 'state': 'awaiting', 'next': 'qr'}

    async def confirm(self, rec, cfg, params, settings):
        gw = rec.setdefault('gateway', {})
        bank_ref = str(params.get('bank_ref') or '').strip()[:40]
        gw['claimed'] = True
        gw['claimed_at'] = _pay_now()
        gw['bank_ref'] = bank_ref
        mode = gw.get('confirm_mode') or cfg.get('confirm_mode') or 'operator'
        if mode == 'customer':
            gw['auth_no'] = bank_ref or ('QR-' + secrets.token_hex(3).upper())
            gw['paid_at'] = _pay_now()
            return {'ok': True, 'state': 'paid', 'paid_ref': gw['auth_no']}
        rec['customer_message'] = 'Thank you - the operator is confirming your payment. Charging starts as soon as it is confirmed.'
        rec['public_data']['claimed'] = True
        return {'ok': True, 'state': 'awaiting', 'next': 'wait_confirm'}


class ManualGateway(PayGateway):
    id = 'manual'
    name = 'Cash / card at the counter'
    kind = 'manual'

    async def begin(self, rec, cfg, params, settings):
        rec['gateway'] = {'by': 'operator', 'note': str(params.get('note') or '')[:120], 'paid_at': _pay_now(),
                          'auth_no': 'MAN-' + secrets.token_hex(3).upper()}
        return {'ok': True, 'state': 'paid', 'paid_ref': rec['gateway']['auth_no']}


class ChargerGateway(PayGateway):
    """Payments taken on the charger's own terminal (reported with DataTransfer PaymentReceived)."""
    id = 'charger'
    name = 'Paid at the charger'
    kind = 'charger'

    async def begin(self, rec, cfg, params, settings):
        return {'ok': True, 'state': 'paid'}


PAY_GATEWAYS = {g.id: g for g in (DemoBankGateway(), RmaBfsGateway(), BhutanQrGateway(), ManualGateway(), ChargerGateway())}

pay_settings = PaymentSettings()
pay_ledger = PaymentLedger()
app_state.payment_auto_accept = bool(pay_settings.data.get('accept_unknown_pay_tags', True))

# Extension points used by the customer app (wallet, accounts, push): event hooks + resolvers.
PAY_HOOKS: Dict[str, list] = {}            # event -> [async fn(rec)], events: paid, charging, completed, failed, cancelled, expired
PAY_EXTENSIONS: Dict[str, Any] = {}        # 'resolve_customer': fn(token)->customer|None, 'config_extra': fn(request, pub)->None,
                                           # 'prepare_record': fn(rec, customer, params)->error|None


def pay_add_hook(event: str, fn):
    PAY_HOOKS.setdefault(event, []).append(fn)


async def _pay_run_hooks(event: str, rec: dict):
    for fn in PAY_HOOKS.get(event, []):
        try:
            await fn(rec)
        except Exception as e:
            logger.error(f"payment hook {event} failed for {rec.get('ref')}: {e}")


# ---------------------------------------------------------------------------
# Flow
# ---------------------------------------------------------------------------
def _pay_station_public(cp_id: str, viewer: str = None) -> dict:
    """Station facts the customer page may see; [OPS] v1.12 a connector kept for the booking of another driver shows as
    Reserved (busy), the viewer's own booked connector stays free for them (viewer = app customer id)."""
    return ops_bk_mark_station(_pay_station_public_raw(cp_id), viewer)


def _pay_station_public_raw(cp_id: str) -> dict:
    """Station facts the customer page may see (no vendor data, no log)."""
    rec = app_state.station_record(cp_id)
    status = rec.get('status') or {}
    connectors = sorted(int(k) for k in status.keys() if str(k).isdigit() and int(k) > 0)
    if not connectors:
        connectors = [1, 2]                                     # nothing reported yet (or offline): show the usual two heads
    out = {'id': cp_id, 'connected': bool(rec.get('connected')), 'registration': rec.get('registration_status'),
           'known': cp_id in app_state.cp_registrations or cp_id in app_state.cp_data, 'connectors': []}
    for c in connectors:
        st = status.get(c) or status.get(str(c)) or 'Unknown'
        active = pay_ledger.active_for_connector(cp_id, c)
        txn = any(int(t.get('connector_id') or 0) == c for t in (rec.get('transactions') or {}).values())
        out['connectors'].append({'id': c, 'status': st, 'busy': bool(active) or txn or st in ('Charging', 'SuspendedEV', 'SuspendedEVSE', 'Finishing', 'Faulted', 'Unavailable'),
                                  'pay_ref': active['ref'] if active else None})
    return out


async def pay_broadcast(rec: dict, event: str = 'update'):
    try:
        await app_state.broadcast('payment_update', {'event': event, 'record': pay_ledger.admin_view(rec), 'kpis': pay_ledger.kpis()})
    except Exception as e:
        logger.debug(f"payment: broadcast failed: {e}")


def _pay_log(rec: dict, action: str, extra: dict = None):
    data = {'ref': rec.get('ref'), 'connector': rec.get('connector_id'), 'amount': rec.get('amount'), 'currency': rec.get('currency'),
            'method': rec.get('method'), 'state': rec.get('state')}
    data.update(extra or {})
    app_state.add_log('💳 PAY', rec.get('cp_id') or 'SYSTEM', action, data)


async def pay_set_state(rec: dict, state: str, detail: str = '', event: str = 'update', log_action: str = None, log_data: dict = None):
    pay_ledger.touch(rec, state=state, state_detail=detail or rec.get('state_detail', ''))
    if log_action:
        data = dict(log_data or {})
        if detail:
            data['detail'] = detail
        _pay_log(rec, log_action, data)
    await pay_broadcast(rec, event)
    if event != 'update':
        await _pay_run_hooks(event, rec)


async def pay_mark_paid(rec: dict, paid_ref: str = '', detail: str = ''):
    if rec.get('state') not in ('created', 'awaiting'):
        return
    rec['paid_at'] = _pay_now()
    rec['next'] = ''
    rec.setdefault('gateway', {})['paid_ref'] = paid_ref or rec.get('gateway', {}).get('auth_no', '')
    rec['customer_message'] = ''
    await pay_set_state(rec, 'paid', detail or 'payment received', event='paid', log_action='PaymentReceived',
                        log_data={'paidRef': paid_ref})
    if rec.get('kind', 'charge') != 'charge':
        return                                   # top-ups etc. are finished by their 'paid' hook (wallet credit)
    await pay_try_start(rec)


async def pay_try_start(rec: dict, by: str = 'auto') -> dict:
    """Send RemoteStartTransaction for a paid session (if the station is online)."""
    if rec.get('state') not in ('paid', 'starting'):
        return {'ok': False, 'error': 'session is not waiting to start (%s)' % rec.get('state')}
    cs = app_state.charge_points.get(rec['cp_id'])
    if cs is None:
        pay_ledger.touch(rec, state_detail='paid - station offline, will start when it reconnects')
        await pay_broadcast(rec)
        return {'ok': False, 'error': 'station offline', 'retry': True}
    if app_state.get_cp_registration_status(rec['cp_id']) != 'Accepted':
        pay_ledger.touch(rec, state_detail='paid - station not accepted in the CSMS yet')
        await pay_broadcast(rec)
        return {'ok': False, 'error': 'station not accepted', 'retry': True}
    if int(rec.get('start_attempts') or 0) >= PAY_START_ATTEMPTS and by == 'auto':
        return {'ok': False, 'error': 'too many start attempts'}
    rec['start_attempts'] = int(rec.get('start_attempts') or 0) + 1
    rec['last_start_at'] = _pay_now()
    await pay_set_state(rec, 'starting', 'RemoteStart sent (attempt %d)' % rec['start_attempts'])
    try:
        result = await cs.cmd_remote_start(rec['ref'], rec.get('connector_id') or None)
    except Exception as e:
        result = {'status': 'Error: %s' % e}
    status = str(result.get('status', '')).split('.')[-1].lower()
    if status == 'accepted':
        pay_ledger.touch(rec, state_detail='RemoteStart accepted - waiting for the charger to start')
        await pay_broadcast(rec)
        return {'ok': True}
    await pay_set_state(rec, 'paid', 'RemoteStart %s' % (result.get('status') or 'rejected'), log_action='PaymentStartFailed')
    return {'ok': False, 'error': 'RemoteStart %s' % result.get('status')}


async def pay_stop(rec: dict, reason: str = 'customer') -> dict:
    cs = app_state.charge_points.get(rec['cp_id'])
    txn = rec.get('transaction_id')
    if cs is None or txn is None:
        return {'ok': False, 'error': 'station offline or no transaction'}
    rec['stop_sent_at'] = _pay_now()
    rec['stop_reason'] = reason
    await pay_set_state(rec, 'stopping', 'RemoteStop sent (%s)' % reason, log_action='PaymentStopRequested')
    try:
        result = await cs.cmd_remote_stop(txn)
    except Exception as e:
        result = {'status': 'Error: %s' % e}
    status = str(result.get('status', '')).split('.')[-1].lower()
    if status != 'accepted':
        await pay_set_state(rec, 'charging', 'RemoteStop %s' % result.get('status'))
        return {'ok': False, 'error': 'RemoteStop %s' % result.get('status')}
    return {'ok': True}


def _pay_usage(rec: dict, energy_wh: float = None, now: datetime = None) -> dict:
    """Used kWh / minutes / amount for a charging session (energy from the meter, time from the clock)."""
    meter_start = rec.get('meter_start')
    kwh = float(rec.get('used_kwh') or 0)
    if energy_wh is not None and meter_start is not None:
        kwh = max(0.0, (float(energy_wh) - float(meter_start)) / 1000.0)
    minutes = float(rec.get('used_minutes') or 0)
    started = rec.get('started_at')
    if started:
        try:
            t0 = datetime.fromisoformat(started.replace('Z', '+00:00'))
            if t0.tzinfo is not None:
                t0 = t0.astimezone().replace(tzinfo=None)
            # never below what was already billed (clock jumps must not refund time)
            minutes = max(minutes, ((now or datetime.now()) - t0).total_seconds() / 60.0)
        except ValueError:
            pass
    tariff = rec.get('tariff') or {}
    used = pay_cost(tariff, kwh, minutes)
    amount = float(rec.get('amount') or 0)
    if used > amount and amount > 0:
        used = _pay_money(amount)                           # prepaid: never bill more than what was paid
    return {'used_kwh': round(kwh, 3), 'used_minutes': round(minutes, 1), 'used_amount': used,
            'remaining_amount': _pay_money(max(0.0, amount - used))}


async def pay_on_start_transaction(cp_id: str, connector_id: int, id_tag: str, transaction_id: int, meter_start: int, timestamp: str):
    rec = pay_ledger.find_by_idtag(id_tag)
    if rec is None or rec.get('cp_id') != cp_id:
        return
    if rec.get('state') not in ('paid', 'starting', 'charging'):
        return
    try:
        started = datetime.fromisoformat(str(timestamp).replace('Z', '+00:00'))
        started = started.astimezone().replace(tzinfo=None) if started.tzinfo else started
        if abs((datetime.now() - started).total_seconds()) > 600:
            started = datetime.now()                        # charger clock far off -> use ours
    except ValueError:
        started = datetime.now()
    pay_ledger.touch(rec, transaction_id=transaction_id, meter_start=meter_start, connector_id=int(connector_id),
                     started_at=started.isoformat(timespec='seconds'), used_kwh=0.0, used_minutes=0.0,
                     used_amount=pay_cost(rec.get('tariff') or {}, 0, 0))
    rec['remaining_amount'] = _pay_money(float(rec['amount']) - float(rec['used_amount']))
    await pay_set_state(rec, 'charging', 'charging - transaction %s' % transaction_id, event='charging', log_action='PaymentChargingStarted',
                        log_data={'txnId': transaction_id})


def _pay_projected_next(rec: dict, power_w: float, now: datetime) -> float:
    """Cost the next MeterValues sample would add at the current power (interval = time since the last one)."""
    tariff = rec.get('tariff') or {}
    last = rec.get('last_mv_at') or ''
    interval = 10.0
    if last:
        try:
            interval = max(5.0, min(120.0, (now - datetime.fromisoformat(last)).total_seconds()))
        except ValueError:
            pass
    kwh = max(0.0, float(power_w or 0)) / 1000.0 * interval / 3600.0
    return kwh * float(tariff.get('per_kwh') or 0) + interval / 60.0 * float(tariff.get('per_minute') or 0)


async def pay_on_meter_values(cp_id: str, connector_id: int, transaction_id, energy_wh: float = None, power_w: float = None):
    """Called from the MeterValues handler: update the usage and - when the budget is (about to be) used up -
    schedule the RemoteStop.  The stop is a separate task: an OCPP handler must answer the charger first
    (python-ocpp reads one message at a time, a call() inside the handler would deadlock until it times out)."""
    rec = pay_ledger.find_by_txn(cp_id, transaction_id)
    if rec is None or rec.get('state') not in ('charging', 'stopping'):
        return
    now = datetime.now()
    usage = _pay_usage(rec, energy_wh, now=now)
    changed = any(abs(float(rec.get(k) or 0) - usage[k]) > 0.0005 for k in ('used_kwh', 'used_amount'))
    projected = _pay_projected_next(rec, power_w, now) if rec['state'] == 'charging' else 0.0
    pay_ledger.touch(rec, force=False, last_mv_at=now.isoformat(timespec='seconds'), **usage)
    if rec['state'] == 'charging' and pay_settings.data.get('auto_stop_on_budget', True) \
            and usage['used_amount'] + projected >= float(rec['amount']) - 1e-9:
        rec['auto_stopped'] = True
        asyncio.create_task(pay_stop(rec, 'budget used up'))
        return
    if changed:
        await pay_broadcast(rec)


async def pay_on_stop_transaction(cp_id: str, transaction_id: int, meter_stop: int, reason: str, energy_wh: float):
    rec = pay_ledger.find_by_txn(cp_id, transaction_id)
    if rec is None:
        return
    usage = _pay_usage(rec, meter_stop)
    refund_amt = usage['remaining_amount']
    threshold = float((rec.get('tariff') or {}).get('refund_threshold') or 0)
    refund = {'status': 'none', 'amount': 0.0, 'ref': '', 'at': ''}
    if refund_amt >= max(0.01, threshold):
        gw = PAY_GATEWAYS.get(rec.get('method'))
        try:
            r = await gw.refund(rec, pay_settings.method(rec.get('method')), refund_amt, pay_settings) if gw else {'status': 'due'}
        except Exception as e:
            r = {'status': 'due', 'note': str(e)}
        refund = {'status': r.get('status', 'due'), 'amount': refund_amt, 'ref': r.get('ref', ''), 'at': _pay_now() if r.get('status') == 'done' else '',
                  'note': r.get('note', '')}
    pay_ledger.touch(rec, stopped_at=_pay_now(), stop_reason=rec.get('stop_reason') or reason or '', refund=refund, **usage)
    await pay_set_state(rec, 'completed', 'stopped (%s) - used %s %.2f' % (reason, rec.get('symbol', ''), usage['used_amount']),
                        event='completed', log_action='PaymentSettled',
                        log_data={'usedKwh': usage['used_kwh'], 'usedAmount': usage['used_amount'], 'refund': refund['status'], 'refundAmount': refund['amount']})


async def pay_on_charger_event(cp_id: str, message_id: str, entry: dict):
    """DataTransfer PaymentReceived / PaymentSettled from a charger with its own payment terminal."""
    if not entry:
        return
    id_tag = str(entry.get('idTag') or '').strip().upper()
    if not id_tag:
        return
    rec = pay_ledger.find_by_idtag(id_tag)
    if message_id == 'PaymentReceived':
        if rec is None:
            amount = _pay_money(entry.get('paidAmount') or entry.get('amount') or 0)
            tariff = {'per_kwh': float(entry.get('tariff') or pay_settings.tariff.get('per_kwh') or 0), 'per_minute': 0.0, 'session_fee': 0.0,
                      'refund_threshold': pay_settings.tariff.get('refund_threshold', 1.0)}
            if str(entry.get('tariffMode') or 'kWh').lower().startswith('min'):
                tariff = {'per_kwh': 0.0, 'per_minute': float(entry.get('tariff') or 0), 'session_fee': 0.0, 'refund_threshold': 1.0}
            rec = pay_ledger.create(cp_id, int(entry.get('connectorId') or 0), amount, 'charger', pay_settings, source='charger', ref=id_tag)
            rec['tariff'] = tariff
            rec['budget'] = pay_budget(tariff, amount)
            rec['currency'] = str(entry.get('currency') or rec['currency'])
            rec['symbol'] = 'Nu.' if rec['currency'] == 'BTN' else rec['currency']
        rec['gateway'] = {'charger_gateway': entry.get('gateway'), 'invoice': entry.get('invoiceNo'), 'paid_ref': entry.get('paidRef'),
                          'session_id': entry.get('sessionId'), 'paid_at': entry.get('paidAt')}
        rec['paid_at'] = _pay_now()
        rec['state_detail'] = 'paid on the charger (%s)' % (entry.get('gateway') or 'terminal')
        if rec['state'] in ('created', 'awaiting', 'paid'):
            rec['state'] = 'paid'
        pay_ledger.touch(rec)
        await pay_broadcast(rec, 'paid')
    elif message_id == 'PaymentSettled' and rec is not None:
        usage = {'used_kwh': float(entry.get('usedKwh') or rec.get('used_kwh') or 0), 'used_minutes': float(entry.get('usedMinutes') or rec.get('used_minutes') or 0),
                 'used_amount': _pay_money(entry.get('usedAmount') or rec.get('used_amount') or 0)}
        usage['remaining_amount'] = _pay_money(entry.get('remainingAmount') if entry.get('remainingAmount') is not None else max(0.0, rec['amount'] - usage['used_amount']))
        rs = str(entry.get('refundStatus') or 'None').lower()
        refund = {'status': 'done' if rs in ('done', 'refunded', 'completed') else ('due' if rs in ('pending', 'due') else 'none'),
                  'amount': _pay_money(entry.get('refundAmount') or 0), 'ref': str(entry.get('refundRef') or ''), 'at': _pay_now() if rs in ('done', 'refunded') else ''}
        pay_ledger.touch(rec, stopped_at=rec.get('stopped_at') or _pay_now(), stop_reason=str(entry.get('endReason') or rec.get('stop_reason') or ''),
                         refund=refund, transaction_id=entry.get('transactionId') or rec.get('transaction_id'), **usage)
        if rec['state'] != 'completed':
            await pay_set_state(rec, 'completed', 'settled by the charger', event='completed')
        else:
            await pay_broadcast(rec)


def pay_authorize(id_tag: str) -> Optional[dict]:
    """IdTagInfo for PAY-* idTags from the ledger (None = not known here)."""
    rec = pay_ledger.find_by_idtag(id_tag)
    if rec is None:
        return None
    if rec.get('state') in ('paid', 'starting', 'charging', 'stopping'):
        return {'status': AuthorizationStatus.accepted}
    if rec.get('state') == 'completed':
        return {'status': AuthorizationStatus.accepted}      # StopTransaction / late Authorize of a finished session
    return {'status': AuthorizationStatus.invalid}


async def pay_watchdog_tick(now: datetime = None):
    """One housekeeping pass: expire unpaid sessions, retry starts, time-based budget, stuck stops."""
    now = now or datetime.now()
    for rec in list(pay_ledger.records.values()):
        st = rec.get('state')
        if st in ('created', 'awaiting'):
            exp = rec.get('expires_at') or ''
            if exp and exp < now.isoformat(timespec='seconds'):
                await pay_set_state(rec, 'expired', 'not paid within %d minutes' % (PAY_UNPAID_TTL // 60), event='expired', log_action='PaymentExpired')
        elif st == 'paid':
            last = rec.get('last_start_at') or ''
            if (not last or (now - datetime.fromisoformat(last)).total_seconds() >= PAY_START_RETRY) and rec['cp_id'] in app_state.charge_points:
                await pay_try_start(rec)
        elif st == 'starting':
            last = rec.get('last_start_at') or ''
            if last and (now - datetime.fromisoformat(last)).total_seconds() >= 120:
                await pay_set_state(rec, 'paid', 'charger did not start the transaction - will retry')
        elif st == 'charging':
            usage = _pay_usage(rec, now=now)
            if abs(usage['used_amount'] - float(rec.get('used_amount') or 0)) >= 0.01:
                pay_ledger.touch(rec, force=False, **usage)
                if pay_settings.data.get('auto_stop_on_budget', True) and usage['used_amount'] >= float(rec['amount']) - 1e-9:
                    rec['auto_stopped'] = True
                    await pay_stop(rec, 'budget used up')
                else:
                    await pay_broadcast(rec)
        elif st == 'stopping':
            sent = rec.get('stop_sent_at') or ''
            if sent and (now - datetime.fromisoformat(sent)).total_seconds() >= 90:
                cs = app_state.charge_points.get(rec['cp_id'])
                if cs is not None and rec.get('transaction_id') in cs.data.transactions:
                    await pay_stop(rec, rec.get('stop_reason') or 'retry')
                else:
                    await pay_set_state(rec, 'completed', 'transaction ended (no StopTransaction seen)', event='completed')
    pay_ledger.flush()


async def pay_watchdog():
    """Every 15 s: housekeeping + ledger flush (started from main())."""
    while True:
        try:
            await asyncio.sleep(15)
            await pay_watchdog_tick()
        except asyncio.CancelledError:
            pay_ledger.flush()
            raise
        except Exception as e:
            logger.error(f"payment watchdog: {e}")


# ---------------------------------------------------------------------------
# Rate limiting for the public (no login) endpoints
# ---------------------------------------------------------------------------
_PAY_RATE: Dict[str, list] = {}


def _pay_rate_ok(ip: str, bucket: str, limit: int, window: int = 60) -> bool:
    key = f'{bucket}:{ip}'
    now = time.time()
    hits = [t for t in _PAY_RATE.get(key, []) if now - t < window]
    if len(hits) >= limit:
        _PAY_RATE[key] = hits
        return False
    hits.append(now)
    _PAY_RATE[key] = hits
    if len(_PAY_RATE) > 5000:
        for k in [k for k, v in _PAY_RATE.items() if not v or now - v[-1] > window]:
            _PAY_RATE.pop(k, None)
    return True


def _pay_base_url(request) -> str:
    env_url = os.environ.get('CSMS_PUBLIC_URL', '').strip().rstrip('/')   # [CLOUD] the deployment's own address wins
    if env_url:
        return env_url
    cfg = (pay_settings.data.get('public_base_url') or '').strip().rstrip('/')
    if cfg:
        return cfg
    if TRUST_PROXY:
        proto = (request.headers.get('X-Forwarded-Proto') or request.scheme or 'http').split(',')[0].strip()
        host = (request.headers.get('X-Forwarded-Host') or request.host or '').split(',')[0].strip()
        return f"{proto}://{host}"
    return f"{request.scheme}://{request.host}"


def _pay_customer_rec(request, data: dict = None):
    """Look up a session by ref + token (customer endpoints)."""
    data = data or {}
    ref = str(data.get('ref') or request.match_info.get('ref') or request.query.get('ref') or '').strip().upper()
    token = str(data.get('token') or request.query.get('token') or '')
    rec = pay_ledger.get(ref)
    if rec is None or not _pay_hmac.compare_digest(token, str(rec.get('token') or '')):
        return None
    return rec


