async def handle_pay_public_station(request):
    cp_id = request.match_info['cp_id']
    return web.json_response(_pay_station_public(cp_id), dumps=lambda o: json.dumps(o, default=str))


async def handle_pay_public_create(request):
    ip = _client_ip(request)
    if not _pay_rate_ok(ip, 'create', 30):
        return web.json_response({'error': 'Too many requests - please wait a minute'}, status=429)
    if not pay_settings.data.get('enabled', True):
        return web.json_response({'error': 'Payments are disabled'}, status=403)
    try:
        data = await request.json()
    except Exception:
        return web.json_response({'error': 'Invalid request'}, status=400)
    cp_id = str(data.get('cp_id') or '').strip()
    method = str(data.get('method') or '').strip()
    try:
        connector_id = int(data.get('connector_id') or 0)
        amount = _pay_money(data.get('amount'))
    except (TypeError, ValueError):
        return web.json_response({'error': 'Invalid amount'}, status=400)
    t = pay_settings.tariff
    if not cp_id or not (cp_id in app_state.cp_registrations or cp_id in app_state.cp_data):
        return web.json_response({'error': 'Unknown station'}, status=404)
    if app_state.get_cp_registration_status(cp_id) != 'Accepted':
        return web.json_response({'error': 'This station is not yet accepted by the operator'}, status=409)
    customer = None
    resolver = PAY_EXTENSIONS.get('resolve_customer')
    if resolver and (data.get('customer_token') or request.headers.get('Authorization', '').startswith('Bearer ')):
        customer = resolver(data.get('customer_token') or request.headers.get('Authorization', '')[7:].strip())
    allowed = pay_settings.enabled_methods() + (['wallet'] if customer is not None and 'wallet' in PAY_GATEWAYS else [])
    if method not in allowed:
        return web.json_response({'error': 'Payment method not available'}, status=400)
    if amount < float(t.get('min_amount') or 0) or amount > float(t.get('max_amount') or 1e12):
        return web.json_response({'error': 'Amount must be between %s and %s' % (t.get('min_amount'), t.get('max_amount'))}, status=400)
    station = _pay_station_public(cp_id, viewer=customer['id'] if customer is not None else None)   # [OPS] v1.12 own booking
    if not station['connected']:
        return web.json_response({'error': 'This station is offline right now'}, status=409)
    conns = {c['id']: c for c in station['connectors']}
    if connector_id not in conns:
        if len(conns) == 1:
            connector_id = list(conns)[0]
        else:
            return web.json_response({'error': 'Choose a connector'}, status=400)
    if conns[connector_id]['busy']:
        return web.json_response({'error': 'This connector is busy (%s)' % conns[connector_id]['status']}, status=409)
    cust_info = {k: str(data.get(k) or '')[:80] for k in ('email', 'phone', 'plate') if data.get(k)}
    cust_info['ip'] = ip
    extra = {'customer_id': customer['id']} if customer is not None else None
    rec = pay_ledger.create(cp_id, connector_id, amount, method, pay_settings, customer=cust_info, extra=extra)
    prep = PAY_EXTENSIONS.get('prepare_record')
    if prep and customer is not None:
        err = prep(rec, customer, data)
        if err:
            await pay_set_state(rec, 'failed', err, event='failed', log_action='PaymentFailed')
            return web.json_response({'error': err, 'ref': rec['ref']}, status=400)
    gw = PAY_GATEWAYS[method]
    try:
        res = await gw.begin(rec, pay_settings.method(method), data, pay_settings)
    except Exception as e:
        logger.exception('payment begin failed')
        res = {'ok': False, 'error': 'Gateway error: %s' % e, 'fatal': True}
    if not res.get('ok'):
        rec['input_error'] = True                 # failed before the gateway was reached (missing bank etc.)
        await pay_set_state(rec, 'failed', res.get('error', 'failed'), event='failed', log_action='PaymentFailed')
        return web.json_response({'error': res.get('error', 'Payment failed'), 'ref': rec['ref']}, status=400)
    rec['next'] = res.get('next', '')
    _pay_log(rec, 'PaymentCreated', {'method': method})
    if res.get('state') == 'paid':
        await pay_mark_paid(rec, res.get('paid_ref', ''))
    else:
        await pay_set_state(rec, res.get('state', 'awaiting'), 'waiting for the customer at the gateway', event='created')
    out = pay_ledger.public_view(rec)
    out['token'] = rec['token']
    return web.json_response(out, dumps=lambda o: json.dumps(o, default=str))


async def handle_pay_public_confirm(request):
    ip = _client_ip(request)
    if not _pay_rate_ok(ip, 'confirm', 30):
        return web.json_response({'error': 'Too many requests - please wait a minute'}, status=429)
    try:
        data = await request.json()
    except Exception:
        return web.json_response({'error': 'Invalid request'}, status=400)
    rec = _pay_customer_rec(request, data)
    if rec is None:
        return web.json_response({'error': 'Unknown payment'}, status=404)
    if rec.get('state') != 'awaiting':
        return web.json_response(pay_ledger.public_view(rec), dumps=lambda o: json.dumps(o, default=str))
    gw = PAY_GATEWAYS[rec['method']]
    try:
        res = await gw.confirm(rec, pay_settings.method(rec['method']), data, pay_settings)
    except Exception as e:
        logger.exception('payment confirm failed')
        res = {'ok': False, 'error': 'Gateway error: %s' % e, 'fatal': True}
    if not res.get('ok'):
        if res.get('fatal'):
            await pay_set_state(rec, 'failed', res.get('error', 'failed'), event='failed', log_action='PaymentFailed')
        else:
            pay_ledger.touch(rec)
        out = pay_ledger.public_view(rec)
        out['error'] = res.get('error', 'Payment failed')
        return web.json_response(out, status=400, dumps=lambda o: json.dumps(o, default=str))
    rec['next'] = res.get('next', '')
    if res.get('state') == 'paid':
        await pay_mark_paid(rec, res.get('paid_ref', ''))
    else:
        pay_ledger.touch(rec)
        await pay_broadcast(rec)
    return web.json_response(pay_ledger.public_view(rec), dumps=lambda o: json.dumps(o, default=str))


async def handle_pay_public_status(request):
    rec = _pay_customer_rec(request)
    if rec is None:
        return web.json_response({'error': 'Unknown payment'}, status=404)
    if rec.get('state') == 'charging':
        cs = app_state.charge_points.get(rec['cp_id'])
        snap = (cs.data.meter.get(rec.get('connector_id')) if cs else None) or {}
        usage = _pay_usage(rec, snap.get('energy_wh'))
        rec.update(usage)
    out = pay_ledger.public_view(rec)
    out['station'] = _pay_station_public(rec['cp_id'], viewer=rec.get('customer_id'))   # [OPS] v1.12 own booking
    cs = app_state.charge_points.get(rec['cp_id'])
    snap = (cs.data.meter.get(rec.get('connector_id')) if cs else None) or {}
    out['live'] = {'power_w': snap.get('power_w'), 'soc': snap.get('soc')}
    return web.json_response(out, dumps=lambda o: json.dumps(o, default=str))


async def handle_pay_public_action(request):
    """start (retry RemoteStart) | stop | cancel - by the customer who paid."""
    if not _pay_rate_ok(_client_ip(request), 'action', 30):
        return web.json_response({'error': 'Too many requests'}, status=429)
    try:
        data = await request.json()
    except Exception:
        return web.json_response({'error': 'Invalid request'}, status=400)
    rec = _pay_customer_rec(request, data)
    if rec is None:
        return web.json_response({'error': 'Unknown payment'}, status=404)
    action = str(data.get('action') or '')
    if action == 'stop' and rec.get('state') in ('charging', 'stopping'):
        res = await pay_stop(rec, 'customer')
    elif action == 'start' and rec.get('state') == 'paid':
        res = await pay_try_start(rec, by='customer')
    elif action == 'cancel' and rec.get('state') in ('created', 'awaiting'):
        try:
            await PAY_GATEWAYS[rec['method']].cancel(rec, pay_settings.method(rec['method']), pay_settings)
        except Exception:
            pass
        await pay_set_state(rec, 'cancelled', 'cancelled by the customer', event='cancelled', log_action='PaymentCancelled')
        res = {'ok': True}
    else:
        res = {'ok': False, 'error': 'action %s not possible in state %s' % (action, rec.get('state'))}
    out = pay_ledger.public_view(rec)
    out.update(res)
    return web.json_response(out, status=200 if res.get('ok') else 409, dumps=lambda o: json.dumps(o, default=str))


async def handle_pay_qr_svg(request):
    """QR of the customer pay URL for a station / connector (stickers, charger displays, the simulator panel)."""
    cp_id = str(request.query.get('cp') or '').strip()[:40]
    conn = str(request.query.get('c') or '').strip()[:3]
    if not cp_id:
        return web.json_response({'error': 'cp required'}, status=400)
    url = _pay_base_url(request) + '/pay/' + _pay_urlparse.quote(cp_id)
    if conn.isdigit() and int(conn) > 0:
        url += '/' + conn
    try:
        scale = max(2, min(20, int(request.query.get('scale') or 6)))
    except ValueError:
        scale = 6
    svg = QrCode.encode(url, 'M').to_svg(scale=scale, border=3)
    return web.Response(text=svg, content_type='image/svg+xml', headers={'Cache-Control': 'public, max-age=600'})


async def handle_pay_webhook(request):
    """Bank / aggregator notification: POST /api/pay/webhook/<secret>  {"reference": "PAY-...", "amount": 250, "bank_ref": "..."}"""
    if not _pay_hmac.compare_digest(request.match_info.get('secret', ''), str(pay_settings.data.get('webhook_secret') or '-')):
        return web.json_response({'error': 'forbidden'}, status=403)
    try:
        data = await request.json()
    except Exception:
        data = dict(await request.post())
    ref = str(data.get('reference') or data.get('ref') or data.get('bill_no') or '').strip().upper()
    rec = pay_ledger.get(ref)
    if rec is None:
        return web.json_response({'error': 'unknown reference'}, status=404)
    if rec.get('state') not in ('created', 'awaiting'):
        return web.json_response({'ok': True, 'state': rec.get('state'), 'note': 'already processed'})
    amount = _pay_money(data.get('amount') or rec['amount'])
    if abs(amount - float(rec['amount'])) > 0.01:
        rec.setdefault('gateway', {})['webhook_amount'] = amount
        pay_ledger.note(rec, 'webhook amount %.2f differs from %.2f' % (amount, rec['amount']))
    rec.setdefault('gateway', {})['webhook'] = {k: str(v)[:120] for k, v in data.items()}
    await pay_mark_paid(rec, str(data.get('bank_ref') or data.get('txn_id') or 'WEBHOOK'), 'confirmed by webhook')
    return web.json_response({'ok': True, 'state': rec.get('state')})


# ---------------------------------------------------------------------------
# Operator endpoints (login required)
# ---------------------------------------------------------------------------
async def handle_pay_settings(request):
    if request.method == 'GET':
        return web.json_response(pay_settings.admin())
    try:
        data = await request.json()
    except Exception:
        return web.json_response({'error': 'Invalid JSON'}, status=400)
    # keys: blank = keep the stored one
    rb = (data.get('methods') or {}).get('rma_bfs') or {}
    for k in ('private_key_pem', 'bfs_public_pem'):
        if k in rb and not str(rb.get(k) or '').strip():
            rb.pop(k)
        elif k in rb:
            try:
                (_pay_rsa_private_numbers if k == 'private_key_pem' else _pay_rsa_public_numbers)(rb[k])
            except Exception as e:
                return web.json_response({'error': '%s: not a valid PEM key (%s)' % (k, e)}, status=400)
    bq = (data.get('methods') or {}).get('bhutan_qr') or {}
    if bq.get('static_payload'):
        try:
            items = dict(emv_parse(str(bq['static_payload']).strip()))
            if '00' not in items:
                raise ValueError('tag 00 missing')
            bq['static_payload'] = str(bq['static_payload']).strip()
            bq['static_crc_ok'] = emv_verify_crc(bq['static_payload'])
        except Exception as e:
            return web.json_response({'error': 'Bhutan QR static payload is not a valid EMVCo QR string (%s)' % e}, status=400)
    data.pop('webhook_secret', None)
    pay_settings.update(data)
    app_state.payment_auto_accept = bool(pay_settings.data.get('accept_unknown_pay_tags', True))
    app_state.add_log('💳 PAY', 'SYSTEM', 'PaymentSettingsChanged', {'methods': pay_settings.enabled_methods(), 'tariff': pay_settings.tariff})
    return web.json_response(pay_settings.admin())


async def handle_pay_sessions(request):
    state = request.query.get('state') or ''
    cp = request.query.get('cp') or ''
    try:
        limit = max(1, min(2000, int(request.query.get('limit') or 300)))
    except ValueError:
        limit = 300
    recs = sorted(pay_ledger.records.values(), key=lambda r: r.get('created_at', ''), reverse=True)
    if state == 'open':
        recs = [r for r in recs if r.get('state') in PAY_ACTIVE_STATES or (r.get('refund') or {}).get('status') == 'due']
    elif state:
        recs = [r for r in recs if r.get('state') == state]
    if cp:
        recs = [r for r in recs if r.get('cp_id') == cp]
    return web.json_response({'records': [pay_ledger.admin_view(r) for r in recs[:limit]], 'kpis': pay_ledger.kpis(),
                              'total': len(recs)}, dumps=lambda o: json.dumps(o, default=str))


async def handle_pay_session_action(request):
    try:
        data = await request.json()
    except Exception:
        return web.json_response({'error': 'Invalid JSON'}, status=400)
    rec = pay_ledger.get(str(data.get('ref') or ''))
    if rec is None:
        return web.json_response({'error': 'Unknown payment'}, status=404)
    action = str(data.get('action') or '')
    note = str(data.get('note') or '').strip()[:200]
    if note:
        pay_ledger.note(rec, note)
    res = {'ok': True}
    if action == 'confirm' and rec.get('state') in ('created', 'awaiting'):
        rec.setdefault('gateway', {})['confirmed_by'] = 'operator'
        await pay_mark_paid(rec, note or 'OPERATOR', 'confirmed by the operator')
    elif action == 'cancel' and rec.get('state') in ('created', 'awaiting', 'paid', 'starting'):
        if rec.get('state') in ('paid', 'starting') and float(rec.get('amount') or 0) > 0:
            rec['refund'] = {'status': 'due', 'amount': float(rec['amount']), 'ref': '', 'at': '', 'note': 'cancelled after payment'}
        await pay_set_state(rec, 'cancelled', 'cancelled by the operator' + (' - ' + note if note else ''), event='cancelled', log_action='PaymentCancelled')
    elif action == 'start' and rec.get('state') in ('paid', 'starting'):
        rec['start_attempts'] = 0
        res = await pay_try_start(rec, by='operator')
    elif action == 'stop' and rec.get('state') in ('charging', 'stopping'):
        res = await pay_stop(rec, 'operator')
    elif action == 'refund_done':
        rf = dict(rec.get('refund') or {})
        rf.update({'status': 'done', 'at': _pay_now(), 'ref': str(data.get('refund_ref') or rf.get('ref') or note or 'manual')})
        if data.get('amount') is not None:
            rf['amount'] = _pay_money(data.get('amount'))
        pay_ledger.touch(rec, refund=rf)
        _pay_log(rec, 'PaymentRefunded', {'refundAmount': rf.get('amount'), 'refundRef': rf.get('ref')})
        await pay_broadcast(rec)
    elif action == 'refund_due':
        rf = dict(rec.get('refund') or {})
        rf.update({'status': 'due', 'amount': _pay_money(data.get('amount') if data.get('amount') is not None else rec.get('remaining_amount') or 0)})
        pay_ledger.touch(rec, refund=rf)
        await pay_broadcast(rec)
    elif action == 'delete' and rec.get('state') in PAY_FINAL_STATES:
        pay_ledger.records.pop(rec['ref'], None)
        pay_ledger.save(force=True)
        await app_state.broadcast('payment_update', {'event': 'deleted', 'record': {'ref': rec['ref'], 'deleted': True}, 'kpis': pay_ledger.kpis()})
        return web.json_response({'ok': True, 'deleted': rec['ref']})
    elif action == 'note':
        pay_ledger.touch(rec)
        await pay_broadcast(rec)
    else:
        return web.json_response({'error': 'action %s not possible in state %s' % (action, rec.get('state'))}, status=409)
    out = {'record': pay_ledger.admin_view(rec)}
    out.update(res)
    return web.json_response(out, status=200 if res.get('ok') else 409, dumps=lambda o: json.dumps(o, default=str))


async def handle_pay_manual(request):
    """Operator records a cash / card payment and starts the session."""
    try:
        data = await request.json()
        cp_id = str(data.get('cp_id') or '').strip()
        connector_id = int(data.get('connector_id') or 0)
        amount = _pay_money(data.get('amount'))
    except Exception:
        return web.json_response({'error': 'Invalid request'}, status=400)
    if not cp_id or not (cp_id in app_state.cp_registrations or cp_id in app_state.cp_data):
        return web.json_response({'error': 'Unknown station'}, status=404)
    if amount <= 0:
        return web.json_response({'error': 'Amount must be positive'}, status=400)
    station = _pay_station_public(cp_id)
    conns = {c['id']: c for c in station['connectors']}
    if connector_id not in conns and len(conns) == 1:
        connector_id = list(conns)[0]
    if connector_id not in conns:
        return web.json_response({'error': 'Choose a connector'}, status=400)
    if conns[connector_id]['busy']:
        return web.json_response({'error': 'This connector is busy (%s)' % conns[connector_id]['status']}, status=409)
    rec = pay_ledger.create(cp_id, connector_id, amount, 'manual', pay_settings, source='operator',
                            customer={k: str(data.get(k) or '')[:80] for k in ('plate', 'phone', 'note') if data.get(k)})
    await PAY_GATEWAYS['manual'].begin(rec, pay_settings.method('manual'), data, pay_settings)
    _pay_log(rec, 'PaymentCreated', {'method': 'manual'})
    await pay_mark_paid(rec, rec['gateway'].get('auth_no', ''), 'recorded by the operator')
    return web.json_response({'ok': True, 'record': pay_ledger.admin_view(rec)}, dumps=lambda o: json.dumps(o, default=str))


async def handle_pay_export(request):
    date = request.query.get('date') or ''
    buf = _pay_io.StringIO()
    w = _pay_csv.writer(buf)
    w.writerow(['ref', 'created_at', 'paid_at', 'station', 'connector', 'method', 'state', 'amount', 'currency', 'used_kwh', 'used_minutes',
                'used_amount', 'remaining_amount', 'refund_status', 'refund_amount', 'refund_ref', 'transaction_id', 'started_at', 'stopped_at',
                'stop_reason', 'bank', 'paid_ref', 'source'])
    for r in sorted(pay_ledger.records.values(), key=lambda r: r.get('created_at', '')):
        if date and not (r.get('created_at') or '').startswith(date):
            continue
        gw = r.get('gateway') or {}
        rf = r.get('refund') or {}
        w.writerow([r.get('ref'), r.get('created_at'), r.get('paid_at'), r.get('cp_id'), r.get('connector_id'), r.get('method'), r.get('state'),
                    r.get('amount'), r.get('currency'), r.get('used_kwh'), r.get('used_minutes'), r.get('used_amount'), r.get('remaining_amount'),
                    rf.get('status'), rf.get('amount'), rf.get('ref'), r.get('transaction_id'), r.get('started_at'), r.get('stopped_at'),
                    r.get('stop_reason'), gw.get('bank_name') or gw.get('bank') or '', gw.get('paid_ref') or gw.get('auth_no') or '', r.get('source')])
    name = 'payments_%s.csv' % (date or datetime.now().strftime('%Y-%m-%d'))
    return web.Response(body=('﻿' + buf.getvalue()).encode('utf-8'), content_type='text/csv',
                        headers={'Content-Disposition': 'attachment; filename="%s"' % name})


async def handle_pay_qr_preview(request):
    """Dynamic Bhutan QR preview for the settings form (uses the form values when given)."""
    cfg = dict(pay_settings.method('bhutan_qr'))
    for k in ('static_payload', 'account_tag', 'account_value', 'mcc'):
        v = request.query.get(k)
        if v is not None and v.strip():
            cfg[k] = v.strip()
    if request.query.get('static_payload') is not None and not request.query.get('static_payload', '').strip():
        cfg['static_payload'] = ''
    try:
        amount = _pay_money(request.query.get('amount') or 100)
        payload = PAY_GATEWAYS['bhutan_qr'].payload(cfg, pay_settings, amount, 'PAY-PREVIEW01')
    except Exception as e:
        return web.json_response({'error': str(e)}, status=400)
    svg = QrCode.encode(payload, 'M').to_svg(scale=5, border=3)
    return web.Response(text=svg, content_type='image/svg+xml', headers={'Cache-Control': 'no-store', 'X-Payload': payload})


async def handle_pay_sticker(request):
    """Printable QR stickers (one per connector) for a station, or for every accepted station (cp=all)."""
    cp_id = str(request.match_info.get('cp_id') or '').strip()
    base = _pay_base_url(request)
    if cp_id == 'all':
        ids = [s['id'] for s in app_state.station_records() if s.get('registration_status') == 'Accepted']
    else:
        ids = [cp_id]
    cards = []
    for sid in ids:
        st = _pay_station_public(sid)
        conns = [c['id'] for c in st['connectors']] or [1, 2]
        for c in conns:
            url = base + '/pay/' + _pay_urlparse.quote(sid) + '/' + str(c)
            svg = QrCode.encode(url, 'M').to_svg(scale=5, border=3)
            cards.append('<div class="card"><img class="logo" src="/static/bpc_logo.png" alt=""><div class="t">%s</div><div class="s">Scan to pay &amp; charge</div>%s'
                         '<div class="id">%s</div><div class="c">Connector %d</div><div class="u">%s</div><div class="f">%s</div></div>'
                         % (html_escape(BRAND_NAME), svg, html_escape(sid), c, html_escape(url), html_escape(pay_settings.data.get('merchant_name') or '')))
    page = PAY_STICKER_TEMPLATE.replace('{{CARDS}}', ''.join(cards)).replace('{{TITLE}}', html_escape('QR stickers - ' + (cp_id if cp_id != 'all' else 'all stations')))
    return web.Response(text=page, content_type='text/html')


def html_escape(s) -> str:
    return (str(s if s is not None else '').replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;'))


def pay_register_routes(app):
    app.router.add_get('/pay', handle_pay_page)
    app.router.add_get('/pay/', handle_pay_page)
    app.router.add_get('/pay/{cp_id}', handle_pay_page)
    app.router.add_get('/pay/{cp_id}/{connector}', handle_pay_page)
    app.router.add_get('/api/pay/public/config', handle_pay_public_config)
    app.router.add_get('/api/pay/public/station/{cp_id}', handle_pay_public_station)
    app.router.add_post('/api/pay/public/create', handle_pay_public_create)
    app.router.add_post('/api/pay/public/confirm', handle_pay_public_confirm)
    app.router.add_get('/api/pay/public/status/{ref}', handle_pay_public_status)
    app.router.add_post('/api/pay/public/action', handle_pay_public_action)
    app.router.add_get('/api/pay/qr.svg', handle_pay_qr_svg)
    app.router.add_post('/api/pay/webhook/{secret}', handle_pay_webhook)
    app.router.add_get('/api/pay/settings', handle_pay_settings)
    app.router.add_post('/api/pay/settings', handle_pay_settings)
    app.router.add_get('/api/pay/sessions', handle_pay_sessions)
    app.router.add_post('/api/pay/session/action', handle_pay_session_action)
    app.router.add_post('/api/pay/manual', handle_pay_manual)
    app.router.add_get('/api/pay/export.csv', handle_pay_export)
    app.router.add_get('/api/pay/sticker/{cp_id}', handle_pay_sticker)
    app.router.add_get('/api/pay/qr_preview.svg', handle_pay_qr_preview)


