# [DEMO-GEO] simulated BPC-<town> chargers get the demo map position of their town (never overwrites a position)
def demo_geo_for_simulator(cp_id: str, firmware: str) -> bool:
    try:
        if not str(firmware or '').upper().startswith('SIM-'):
            return False
        si = globals().get('station_info')
        if si is None:
            return False
        cp = str(cp_id or '')
        town = (cp.upper().split('-', 1)[1] if '-' in cp else cp.upper()).replace(' ', '')
        if town not in APP_DEMO_TOWNS or (si.data.get(cp) or {}).get('lat'):
            return False
        lat, lon, name, addr = APP_DEMO_TOWNS[town]
        si.data[cp] = dict(si.data.get(cp) or {}, name=f'BPC {name}', address=addr, lat=lat, lon=lon)
        si.save()
        logger.info(f"📍 {cp}: simulated charger placed at the demo position of {name}")
        return True
    except Exception as e:
        logger.warning(f"demo position for {cp_id} failed: {e}")
        return False


def _app_b64url(data: bytes) -> str:
    return _pay_b64.urlsafe_b64encode(data).decode().rstrip('=')


def _app_b64url_decode(s: str) -> bytes:
    s = str(s or '')
    return _pay_b64.urlsafe_b64decode(s + '=' * (-len(s) % 4))


def _app_atomic_write(path: str, data) -> None:
    tmp = path + '.tmp'
    with open(tmp, 'w', encoding='utf-8') as f:
        json.dump(data, f, indent=1, ensure_ascii=False, default=str)
    os.replace(tmp, path)


def _app_json_load(path: str, default):
    try:
        if os.path.exists(path):
            with open(path, 'r', encoding='utf-8') as f:
                return json.load(f)
    except Exception as e:
        logger.error(f"app: failed to load {path}: {e}")
    return default


def _app_norm_phone(p: str) -> str:
    p = ''.join(ch for ch in str(p or '') if ch.isdigit() or ch == '+')
    if p.startswith('+975'):
        p = p[4:]
    elif p.startswith('975') and len(p) == 11:
        p = p[3:]
    return p.lstrip('+')


def _app_hash_password(password: str, salt: bytes = None) -> dict:
    salt = salt or secrets.token_bytes(16)
    h = _pay_hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, APP_PBKDF2_ITER)
    return {'salt': _app_b64url(salt), 'hash': _app_b64url(h), 'iter': APP_PBKDF2_ITER}


def _app_check_password(password: str, stored: dict) -> bool:
    try:
        h = _pay_hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), _app_b64url_decode(stored['salt']), int(stored.get('iter') or APP_PBKDF2_ITER))
        return _pay_hmac.compare_digest(_app_b64url(h), stored['hash'])
    except Exception:
        return False


# ---------------------------------------------------------------------------
# Settings
# ---------------------------------------------------------------------------
class AppSettings:
    def __init__(self):
        saved, _src = _db_load_doc('settings', 'app', lambda: _app_json_load(APP_SETTINGS_FILE, {}))
        self.data = _pay_deep_merge(APP_DEFAULT_SETTINGS, saved if isinstance(saved, dict) else {})
        if not self.data.get('vapid', {}).get('public_key'):
            self.data['vapid'] = app_vapid_generate()
            self.save()

    def save(self, force_files: bool = False):
        db = _db()
        if db is not None:
            try:
                db.put_doc('settings', 'app', self.data)
            except Exception as e:
                logger.error(f"app: database save failed: {e}")
        if db is None or force_files or _db_keep_files():
            try:
                _app_atomic_write(APP_SETTINGS_FILE, self.data)
            except Exception as e:
                logger.error(f"app: failed to save {APP_SETTINGS_FILE}: {e}")

    def update(self, changes: dict) -> dict:
        changes = dict(changes or {})
        changes.pop('vapid', None)
        merged = _pay_deep_merge(self.data, changes)
        tiers = []
        for t in (merged.get('membership', {}).get('tiers') or []):
            try:
                tiers.append({'name': str(t.get('name') or 'Tier')[:20], 'min_kwh': max(0.0, float(t.get('min_kwh') or 0)),
                              'discount_pct': max(0.0, min(90.0, float(t.get('discount_pct') or 0)))})
            except (TypeError, ValueError):
                continue
        tiers.sort(key=lambda t: t['min_kwh'])
        if not tiers or tiers[0]['min_kwh'] > 0:
            tiers.insert(0, {'name': 'Standard', 'min_kwh': 0, 'discount_pct': 0})
        merged['membership']['tiers'] = tiers
        bonus = []
        for b in (merged.get('topup_bonus') or []):
            try:
                bonus.append({'min': max(0.0, float(b.get('min') or 0)), 'bonus': max(0.0, float(b.get('bonus') or 0))})
            except (TypeError, ValueError):
                continue
        merged['topup_bonus'] = sorted(bonus, key=lambda b: b['min'])
        promos = []
        for p in (merged.get('promos') or []):
            code = str(p.get('code') or '').strip().upper()[:20]
            if not code or p.get('type') not in ('pct', 'bonus_amount', 'bonus_pct'):
                continue
            try:
                promos.append({'code': code, 'type': p['type'], 'value': max(0.0, float(p.get('value') or 0)),
                               'min_amount': max(0.0, float(p.get('min_amount') or 0)), 'expires': str(p.get('expires') or '')[:10],
                               'max_uses': int(p.get('max_uses') or 0), 'used': int(p.get('used') or 0), 'active': bool(p.get('active', True)),
                               'note': str(p.get('note') or '')[:80], 'once_per_customer': bool(p.get('once_per_customer', True)),
                               'used_by': list(p.get('used_by') or [])[:5000]})
            except (TypeError, ValueError):
                continue
        merged['promos'] = promos
        merged['welcome_bonus'] = max(0.0, _pay_money(merged.get('welcome_bonus') or 0))
        m = dict(merged.get('map') or {})
        m['tile_url'] = str(m.get('tile_url') or '').strip() or APP_DEFAULT_SETTINGS['map']['tile_url']
        m['proxy'] = bool(m.get('proxy', True))
        try:
            m['zoom'] = max(3, min(18, int(m.get('zoom') or 8)))
        except (TypeError, ValueError):
            m['zoom'] = 8
        if m['tile_url'] != (self.data.get('map') or {}).get('tile_url'):
            app_tile_cache_reset()
        merged['map'] = m
        self.data = merged
        self.save()
        return self.data

    def tiers(self) -> list:
        return self.data.get('membership', {}).get('tiers') or [{'name': 'Standard', 'min_kwh': 0, 'discount_pct': 0}]

    def tier_for(self, kwh: float) -> dict:
        cur = self.tiers()[0]
        for t in self.tiers():
            if kwh >= float(t.get('min_kwh') or 0):
                cur = t
        return cur

    def next_tier(self, kwh: float) -> Optional[dict]:
        for t in self.tiers():
            if kwh < float(t.get('min_kwh') or 0):
                return t
        return None

    def promo(self, code: str) -> Optional[dict]:
        code = str(code or '').strip().upper()
        for p in self.data.get('promos') or []:
            if p.get('code') == code:
                return p
        return None

    def public(self) -> dict:
        m = {k: v for k, v in (self.data.get('map') or {}).items()}
        if m.get('proxy', True):
            m['tile_url'] = APP_TILE_PROXY_URL           # the phone never talks to the tile provider directly
        return {'app_name': self.data.get('app_name'), 'tiers': self.tiers(), 'topup_bonus': self.data.get('topup_bonus') or [],
                'map': m, 'push_public_key': self.data.get('vapid', {}).get('public_key', ''),
                'push_enabled': bool(self.data.get('push_enabled')) and bool(self.data.get('vapid', {}).get('public_key')),
                'support_phone': self.data.get('support_phone', ''), 'currency': pay_settings.data.get('currency', 'BTN'),
                'symbol': pay_settings.data.get('currency_symbol', 'Nu.'), 'tariff': pay_settings.public()['tariff'],
                'methods': pay_settings.public()['methods'], 'brand': BRAND_NAME}

    def admin(self) -> dict:
        d = json.loads(json.dumps(self.data))
        d['vapid'] = {'public_key': d.get('vapid', {}).get('public_key', ''), 'private_set': bool(d.get('vapid', {}).get('private_pem'))}
        d['push_available'] = app_push_available()
        d['tile_status'] = _app_tile_state['status']
        d['tile_cache'] = len(_app_tile_mem)
        return d


# ---------------------------------------------------------------------------
# Customers
# ---------------------------------------------------------------------------
class CustomerStore:
    PUBLIC = ('id', 'name', 'phone', 'email', 'plate', 'lang', 'created_at', 'balance', 'stats', 'last_login', 'blocked')

    def __init__(self):
        cache = {}

        def file_data():
            if 'data' not in cache:
                cache['data'] = _app_json_load(APP_CUSTOMERS_FILE, {}) or {}
            return cache['data']
        self.customers, src = _db_load_collection('customers', lambda: {c['id']: c for c in (file_data().get('customers') or []) if isinstance(c, dict) and c.get('id')})
        self.customers = {k: v for k, v in self.customers.items() if isinstance(v, dict) and v.get('id')}
        self.tokens, _ = _db_load_collection('tokens', lambda: dict(file_data().get('tokens') or {}))
        self._dirty = False
        self._last_save = 0.0
        now = time.time()
        self.tokens = {t: v for t, v in self.tokens.items() if isinstance(v, dict) and float(v.get('expires', 0)) > now}
        logger.info(f"app: loaded {len(self.customers)} customers ({src})")

    def save(self, force: bool = False):
        self._dirty = True
        if not force and time.time() - self._last_save < 2.0:
            return
        self.flush()

    def flush(self, force_files: bool = False):
        if not self._dirty and not force_files:
            return
        try:
            db = _db()
            if db is not None:
                db.sync_collection('customers', self.customers)     # [DB] changed customers only
                db.sync_collection('tokens', self.tokens)
            if db is None or force_files or _db_keep_files():
                _app_atomic_write(APP_CUSTOMERS_FILE, {'customers': list(self.customers.values()), 'tokens': self.tokens})
            self._dirty = False
            self._last_save = time.time()
        except Exception as e:
            logger.error(f"app: failed to save {APP_CUSTOMERS_FILE}: {e}")

    # ---- lookup
    def by_login(self, login: str) -> Optional[dict]:
        login = str(login or '').strip()
        if not login:
            return None
        phone = _app_norm_phone(login)
        email = login.lower()
        for c in self.customers.values():
            if (phone and c.get('phone') == phone) or (c.get('email') and c['email'] == email):
                return c
        return None

    def get(self, cid: str) -> Optional[dict]:
        return self.customers.get(str(cid or ''))

    # ---- accounts
    def create(self, name: str, phone: str, password: str, email: str = '', plate: str = '', lang: str = 'en') -> dict:
        cid = 'C' + secrets.token_hex(4).upper()
        while cid in self.customers:
            cid = 'C' + secrets.token_hex(4).upper()
        now = _pay_now()
        c = {'id': cid, 'name': name.strip()[:60], 'phone': _app_norm_phone(phone), 'email': email.strip().lower()[:80], 'plate': plate.strip().upper()[:20],
             'lang': lang if lang in ('en', 'dz', 'th') else 'en', 'password': _app_hash_password(password), 'created_at': now, 'last_login': now,
             'balance': 0.0, 'wallet': [], 'stats': {'sessions': 0, 'kwh': 0.0, 'spent': 0.0}, 'push': [], 'notifications': [],
             'promos_used': [], 'blocked': False}
        self.customers[cid] = c
        self.save(force=True)
        return c

    def issue_token(self, c: dict, ua: str = '') -> str:
        tok = secrets.token_urlsafe(32)
        self.tokens[tok] = {'customer_id': c['id'], 'created': time.time(), 'expires': time.time() + APP_TOKEN_TTL, 'ua': str(ua or '')[:120]}
        c['last_login'] = _pay_now()
        # keep at most 10 tokens per customer
        mine = sorted([(v['created'], t) for t, v in self.tokens.items() if v.get('customer_id') == c['id']])
        for _, t in mine[:-10]:
            self.tokens.pop(t, None)
        self.save(force=True)
        return tok

    def resolve(self, token: str) -> Optional[dict]:
        rec = self.tokens.get(str(token or ''))
        if not rec or float(rec.get('expires', 0)) < time.time():
            return None
        c = self.customers.get(rec['customer_id'])
        if c is None or c.get('blocked'):
            return None
        return c

    def revoke(self, token: str):
        if self.tokens.pop(str(token or ''), None) is not None:
            self.save(force=True)

    # ---- wallet
    def wallet_add(self, c: dict, kind: str, amount: float, ref: str = '', note: str = '') -> dict:
        amount = _pay_money(amount)
        c['balance'] = _pay_money(float(c.get('balance') or 0) + amount)
        entry = {'at': _pay_now(), 'type': kind, 'amount': amount, 'ref': ref, 'note': str(note or '')[:120], 'balance_after': c['balance']}
        c.setdefault('wallet', []).append(entry)
        c['wallet'] = c['wallet'][-APP_MAX_WALLET_ENTRIES:]
        self.save(force=True)
        return entry

    # ---- notifications
    def notify(self, c: dict, title: str, body: str, url: str = '', kind: str = 'info', ref: str = '') -> dict:
        n = {'id': secrets.token_hex(4), 'at': _pay_now(), 'title': str(title)[:80], 'body': str(body)[:300], 'url': url, 'kind': kind, 'ref': ref, 'read': False}
        c.setdefault('notifications', []).insert(0, n)
        c['notifications'] = c['notifications'][:APP_MAX_NOTIFICATIONS]
        self.save()
        return n

    def public_view(self, c: dict) -> dict:
        d = {k: c.get(k) for k in self.PUBLIC}
        kwh = float((c.get('stats') or {}).get('kwh') or 0)
        tier = app_settings.tier_for(kwh)
        nxt = app_settings.next_tier(kwh)
        d['tier'] = tier
        d['next_tier'] = nxt
        d['tier_progress'] = (min(1.0, kwh / float(nxt['min_kwh'])) if nxt and float(nxt['min_kwh']) > 0 else 1.0)
        d['unread'] = sum(1 for n in c.get('notifications') or [] if not n.get('read'))
        d['push_subscribed'] = len(c.get('push') or [])
        return d

    def admin_view(self, c: dict) -> dict:
        d = self.public_view(c)
        d['push'] = len(c.get('push') or [])
        d['wallet_entries'] = len(c.get('wallet') or [])
        d['promos_used'] = c.get('promos_used') or []
        return d


